// 由 script/gen-static.ts 生成，勿手改。
export const WEB_STATIC: Readonly<Record<string, string>> = {
  "app.js": "// ============================================================\r\n// shell/webui/app.js —— WebUIShell 浏览器应用脚本（三件套之分文件）\r\n//\r\n// 结构（批 3 布局）：左栏 = 标题（隠/設）+ 族谱树（状态字前置 + 浮动「選」\r\n// 菜单）+ 实例化面板 + 快捷设置（模型环/思考程度占位）；主区 = 无边框文档流\r\n// timeline + composer（输入框在上、信息条行在下：附钮左 · 六项元信息中 ·\r\n// 状态+连接右 · 送钮右）+ 铺底占用条。header 已废除——agent 事实进信息条，\r\n// 动作进二级菜单与设置面板（模态，实例/类双页签）。\r\n// 流式 live 层纪律：delta live-only（applyStreamEvent 分桶），轮末 letter →\r\n// loadContext 快照收口不补间隙；思维链折叠 running 追最新行、结束定格首行\r\n// （summary 与 rest 零重复）；rAF 合帧节流。全部纯逻辑住 view.js（可测）。\r\n// ============================================================\r\n\r\nimport { ACT_GLYPH, ROOT_ID, applyStreamEvent, clearBucket, composerMeta, computeTreeRows, contextRatio, createLiveBuckets, deriveActions, infoRows, mdToHtml, menuItems, ratioTone, reasoningView, relativeTime, routeLetters, statusGlyph, statusTone, toolFold, truncate, turnStats } from './view.js'\r\n\r\nconst $ = (id) => document.getElementById(id)\r\nconst timeline = $('timeline')\r\nlet currentAgentId = ''\r\nlet agentsCache = []\r\nlet templatesCache = []\r\n\r\n// —— 流式 live 层状态 ——\r\nconst liveBuckets = createLiveBuckets()\r\nlet watchAgentId = '' // 监督抽屉目标（'' = 关）\r\nlet liveHost = null\r\nlet ctxWindow = 1000000\r\nlet ctxRatio = 0\r\nlet paintQueued = false\r\n\r\n// ---------- 族谱侧栏 ----------\r\n\r\nfunction lanesSvg(row) {\r\n  const L = 14, half = 12\r\n  const parts = []\r\n  const color = row.type === 'node' ? (row.family === 0 ? 'var(--accent)' : row.family === 1 ? 'var(--muted)' : 'var(--border-strong)') : 'var(--border-strong)'\r\n  for (const lane of row.passThrough ?? []) {\r\n    parts.push(`<line x1=\"${(lane + 0.5) * L}\" y1=\"0\" x2=\"${(lane + 0.5) * L}\" y2=\"24\" stroke=\"${color}\" stroke-width=\"1\" opacity=\".55\"/>`)\r\n  }\r\n  if (row.type === 'node') {\r\n    const cx = (row.lane + 0.5) * L\r\n    if (row.join && row.parentLane !== null) {\r\n      const px = (row.parentLane + 0.5) * L\r\n      if (px === cx) parts.push(`<line x1=\"${px}\" y1=\"0\" x2=\"${cx}\" y2=\"${half}\" stroke=\"${color}\" stroke-width=\"1\"/>`)\r\n      else parts.push(`<path d=\"M ${px} 0 L ${px} ${half} L ${cx} ${half}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"1\"/>`)\r\n    }\r\n    parts.push(`<circle cx=\"${cx}\" cy=\"${half}\" r=\"3\" fill=\"${row.isRoot ? 'none' : color}\" stroke=\"${color}\" stroke-width=\"1.5\"/>`)\r\n  } else {\r\n    parts.push(`<text x=\"${(row.lane + 0.5) * L - 3}\" y=\"15\" fill=\"var(--muted)\" font-size=\"11\">└</text>`)\r\n  }\r\n  return `<svg class=\"lanes\" viewBox=\"0 0 ${5 * L} 24\" aria-hidden=\"true\">${parts.join('')}</svg>`\r\n}\r\n\r\nasync function loadAgents(prefetched) {\r\n  const agents = prefetched ?? await fetch('/api/agents').then((r) => r.json())\r\n  agentsCache = agents\r\n  const tree = $('tree')\r\n  tree.innerHTML = ''\r\n  for (const row of computeTreeRows(agents)) {\r\n    const el = document.createElement('div')\r\n    if (row.type === 'more') {\r\n      el.className = 'tnode moren'\r\n      const label = row.kind === 'siblings' ? `… +${row.count} 兄弟（共 ${row.descendants} 实例）` : `… +${row.count} 后代（更深层折叠）`\r\n      el.innerHTML = lanesSvg(row) + `<span>${label}</span>`\r\n      tree.appendChild(el)\r\n      continue\r\n    }\r\n    const a = row.row\r\n    el.className = 'tnode' + (a.id === currentAgentId ? ' active' : '') + (row.isRoot ? ' rootnode' : '')\r\n    const tone = statusTone(a.status)\r\n    const glyph = row.isRoot ? ACT_GLYPH.me : statusGlyph(a.status)\r\n    const lp = a.lastPrompt ? truncate(a.lastPrompt, 24) : `<${a.classRef ?? ''}>`\r\n    // 状态字前置；「選」钮 CSS 绝对浮动（平时零占位不挤行）\r\n    el.innerHTML = lanesSvg(row) + `<span class=\"st tone-${tone}\">${glyph}</span><span class=\"id\">${esc(String(a.name ?? a.id))}</span><span class=\"lp\">${esc(decodeEntities(lp))}</span>` +\r\n      (row.isRoot ? '' : `<span class=\"mbtn\" title=\"操作菜单\">選</span>`)\r\n    el.onclick = () => selectAgent(a.id)\r\n    el.oncontextmenu = (e) => { e.preventDefault(); openMenu(a, e.clientX, e.clientY) }\r\n    const mb = el.querySelector('.mbtn')\r\n    if (mb !== null) mb.addEventListener('click', (e) => { e.stopPropagation(); const r = mb.getBoundingClientRect(); openMenu(a, r.left - 120, r.bottom + 2) })\r\n    bindHover(el, a.id)\r\n    tree.appendChild(el)\r\n  }\r\n  renderComposerMeta()\r\n  renderQuickBox()\r\n}\r\n\r\nconst decodeEntities = (s) => String(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>')\r\nconst currentAgent = () => agentsCache.find((x) => x.id === currentAgentId) ?? null\r\n// 呈现面统一 name#id：routeLetters 的发送者标签由它把裸 id 转全名（B4）。\r\nconst nameOf = (id) => { const a = agentsCache.find((x) => x.id === id); return a !== undefined && a.name !== undefined ? a.name : undefined }\r\n\r\n// —— composer 信息条（header 废除后 agent 事实的家）：六项元信息 + 右端状态/连接 ——\r\nfunction renderComposerMeta() {\r\n  const a = currentAgent()\r\n  $('cMeta').innerHTML = a === null ? '<span class=\"item\"><span class=\"k\">族谱全景 · 选择一位后代开始对话</span></span>'\r\n    : composerMeta(a).map((r, i) => `<span class=\"item${i === 0 ? ' head' : ''}\" title=\"${esc(r.k)}\"><span class=\"k\">${esc(r.k)}</span><span class=\"v\">${esc(r.v)}</span></span>`).join('')\r\n  const cr = $('cRight')\r\n  // 注意：重建 cRight 会销毁静态 #conn——读写一律 null-safe（?.），且把连接态\r\n  // 随重建传递（旧版在此 throw TypeError 截断 selectAgent 后续渲染，事故修复）。\r\n  const connOn = $('conn')?.classList.contains('on') === true\r\n  if (a === null) { cr.innerHTML = `<span id=\"conn\" class=\"${connOn ? 'on' : ''}\" title=\"事件流连接\"></span>`; cr.className = '' }\r\n  else {\r\n    cr.innerHTML = `<span id=\"agentSt\">${esc(statusGlyph(a.status))} ${esc(String(a.status ?? ''))}</span><span id=\"conn\" class=\"${connOn ? 'on' : ''}\" title=\"事件流连接\"></span>`\r\n    cr.className = 'tone-' + statusTone(a.status)\r\n  }\r\n}\r\n\r\n// —— 左栏底：快捷设置（当前 agent 的模型环 + 思考程度占位） ——\r\nfunction renderQuickBox() {\r\n  const a = currentAgent()\r\n  $('quickBox').hidden = a === null\r\n  if (a === null) return\r\n  $('quickName').textContent = `${String(a.name ?? a.id)}#${a.id}`\r\n  renderModelRow(a)\r\n}\r\n\r\nconst ORIGIN_LABEL = { explicit: '显式', class: '类基因', inherited: '父继承', home: '家学' }\r\nlet modelRefs = []\r\n\r\nasync function loadModels() {\r\n  const data = await fetch('/api/models').then((r) => r.json())\r\n  modelRefs = data.refs ?? []\r\n  const cm = $('createModel')\r\n  cm.innerHTML = ''\r\n  cm.add(new Option('模型：继承链（类基因>父继承>家学）', ''))\r\n  for (const ref of modelRefs) cm.add(new Option('出生显式 · ' + ref, ref))\r\n}\r\n\r\nfunction renderModelRow(agent) {\r\n  const cur = agent === null || agent === undefined ? '' : String(agent.model ?? '')\r\n  const origin = agent !== null && agent !== undefined ? ORIGIN_LABEL[agent.modelOrigin] ?? agent.modelOrigin ?? '' : ''\r\n  for (const [sel, badge, inheritLabel] of [[$('modelSel'), $('modelOrigin'), '继承链'], [$('stModel'), $('stModelOrigin'), '继承链']]) {\r\n    sel.innerHTML = ''\r\n    if (cur === '') {\r\n      sel.disabled = true\r\n      sel.appendChild(new Option('（走继承链）', ''))\r\n      badge.textContent = inheritLabel\r\n      continue\r\n    }\r\n    sel.disabled = false\r\n    const refs = modelRefs.includes(cur) ? modelRefs : [cur, ...modelRefs]\r\n    for (const ref of refs) sel.appendChild(new Option(ref, ref))\r\n    sel.value = cur\r\n    badge.textContent = String(origin)\r\n  }\r\n}\r\n\r\nasync function setModel(ref) {\r\n  if (!currentAgentId || ref === '') return\r\n  await fetch('/api/set_model', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: currentAgentId, model: ref }) })\r\n  await loadAgents()\r\n}\r\n$('modelSel').onchange = () => void setModel($('modelSel').value)\r\n$('stModel').onchange = () => void setModel($('stModel').value)\r\n\r\n// —— 悬浮详情卡（infoRows 与数据源同源） ——\r\nlet hoverTimer = 0\r\nlet hideTimer = 0\r\nfunction bindHover(el, id) {\r\n  el.addEventListener('mouseenter', () => {\r\n    clearTimeout(hideTimer)\r\n    hoverTimer = setTimeout(() => {\r\n      const a = agentsCache.find((x) => x.id === id)\r\n      if (a === undefined) return\r\n      const r = el.getBoundingClientRect()\r\n      const card = $('hoverCard')\r\n      card.innerHTML = `<div class=\"t\">${esc(String(a.name ?? a.id))}#${esc(a.id)}</div><div class=\"r\">` +\r\n        infoRows(a).map((row) => `<span>${esc(row.k)}</span><b>${esc(row.v)}</b>`).join('') +\r\n        `</div><div class=\"r\" style=\"margin-top:3px\"><span>最近对话</span><b>${esc(a.lastPrompt ? truncate(a.lastPrompt, 28) : '—')}</b></div>`\r\n      card.hidden = false\r\n      card.style.left = Math.min(r.right + 6, innerWidth - 268) + 'px'\r\n      card.style.top = Math.min(r.top, innerHeight - card.offsetHeight - 8) + 'px'\r\n    }, 400)\r\n  })\r\n  el.addEventListener('mouseleave', () => {\r\n    clearTimeout(hoverTimer)\r\n    hideTimer = setTimeout(() => { $('hoverCard').hidden = true }, 150)\r\n  })\r\n  el.addEventListener('mousedown', () => clearTimeout(hoverTimer))\r\n}\r\n\r\n// —— 二级操作菜单（树行「選」/右击；对话/监督/中断/压缩/改名/配置/销毁） ——\r\nfunction openMenu(agent, x, y) {\r\n  const m = $('popover')\r\n  m.innerHTML = ''\r\n  for (const it of menuItems(agent)) {\r\n    const b = document.createElement('button')\r\n    b.textContent = it.label\r\n    b.dataset.state = it.state\r\n    if (it.danger === true) b.className = 'danger'\r\n    if (it.state !== 'off') b.onclick = () => { closeMenu(); void runMenuAction(it.key, agent) }\r\n    m.appendChild(b)\r\n  }\r\n  m.hidden = false\r\n  m.style.left = Math.min(x, innerWidth - m.offsetWidth - 8) + 'px'\r\n  m.style.top = Math.min(y, innerHeight - m.offsetHeight - 8) + 'px'\r\n}\r\nfunction closeMenu() { $('popover').hidden = true }\r\ndocument.addEventListener('click', (e) => { const m = $('popover'); if (!m.hidden && !m.contains(e.target)) closeMenu() })\r\n\r\nasync function runMenuAction(key, agent) {\r\n  switch (key) {\r\n    case 'open': await selectAgent(agent.id); break\r\n    case 'watch': (watchAgentId === agent.id ? closeDrawer : openDrawer)(agent.id); break\r\n    case 'interrupt': await fetch('/api/interrupt', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: agent.id }) }); break\r\n    case 'compact':\r\n      await fetch('/api/context_action', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: agent.id, action: 'compact' }) })\r\n      if (agent.id === currentAgentId) await loadContext(agent.id)\r\n      break\r\n    case 'rename': await selectAgent(agent.id); openSettings(agent, 'instance'); $('renameInput').focus(); break\r\n    case 'instanceCfg': openSettings(agent, 'instance'); break\r\n    case 'classCfg': openSettings(agent, 'class'); break\r\n    case 'terminate': await terminateAgent(agent); break\r\n  }\r\n}\r\n\r\n// —— 设置面板（模态双页签：实例参数 + 类定义进化面） ——\r\nlet settingsAgent = null\r\nfunction openSettings(agent, tab = 'instance') {\r\n  settingsAgent = agent\r\n  $('settingsMask').hidden = false\r\n  $('stAgent').textContent = `${String(agent.name ?? agent.id)}#${agent.id}`\r\n  $('renameInput').placeholder = `当前「${String(agent.name ?? agent.id)}」→ 新称呼`\r\n  $('renameInput').value = ''\r\n  $('classHint').textContent = ''\r\n  renderModelRow(currentAgent() ?? agent)\r\n  fillClassForm(agent.classRef ?? '')\r\n  switchCfgTab(tab)\r\n}\r\nfunction closeSettings() { settingsAgent = null; $('settingsMask').hidden = true }\r\n$('stClose').onclick = closeSettings\r\n$('settingsMask').addEventListener('click', (e) => { if (e.target === $('settingsMask')) closeSettings() })\r\ndocument.addEventListener('keydown', (e) => { if (e.key === 'Escape') { closeSettings(); closeMenu() } })\r\n$('settingsBtn').onclick = () => openSettings(currentAgent() ?? agentsCache.find((x) => x.id === ROOT_ID) ?? { id: ROOT_ID, name: 'user' })\r\n\r\n// 类页签：下拉 = 装载类全集（panel 只读）；字段回填自 templatesCache 现值。\r\nfunction fillClassForm(classRef) {\r\n  const sel = $('stClassSel')\r\n  sel.innerHTML = ''\r\n  for (const t of templatesCache) sel.appendChild(new Option(t.panel ? `${t.name}（面板·只读）` : t.name, t.name))\r\n  if (templatesCache.some((t) => t.name === classRef)) sel.value = String(classRef)\r\n  prefillClass()\r\n}\r\nfunction prefillClass() {\r\n  const t = templatesCache.find((x) => x.name === $('stClassSel').value)\r\n  const locked = t === undefined || t.panel === true\r\n  $('stClassDesc').value = t?.description ?? ''\r\n  $('stClassPrompt').value = t?.systemPrompt ?? ''\r\n  $('stClassStrategy').value = t?.contextStrategy ?? ''\r\n  $('stClassTools').textContent = t === undefined ? '' : t.tools === undefined ? '工具：继承父档案' : `工具：${Object.entries(t.tools).map(([k, v]) => `${k}=${v}`).join(' ') || '本地封闭'}`\r\n  for (const el of [$('stClassDesc'), $('stClassPrompt'), $('stClassStrategy'), $('classSaveBtn')]) el.disabled = locked\r\n  $('classHint').textContent = t !== undefined && t.panel ? '面板类不可编辑（user/策略 role 红线）' : ''\r\n}\r\n$('stClassSel').onchange = prefillClass\r\n$('classSaveBtn').onclick = async () => {\r\n  const name = $('stClassSel').value\r\n  if (name === '') return\r\n  const r = await fetch('/api/class_update', {\r\n    method: 'POST',\r\n    headers: { 'Content-Type': 'application/json' },\r\n    body: JSON.stringify({ name, description: $('stClassDesc').value, systemPrompt: $('stClassPrompt').value, contextStrategy: $('stClassStrategy').value }),\r\n  }).then((x) => x.json())\r\n  if (r.error !== undefined) { $('classHint').textContent = String(r.error); return }\r\n  $('classHint').textContent = r.persisted ? '已合并落盘（只影响后续实例）' : '已合并（内存，无落盘通道）'\r\n  await loadTemplates()\r\n}\r\n\r\nfunction switchCfgTab(tab) {\r\n  for (const b of $('stTabs').querySelectorAll('button')) b.classList.toggle('on', b.dataset.tab === tab)\r\n  $('stInstance').hidden = tab !== 'instance'\r\n  $('stClass').hidden = tab !== 'class'\r\n}\r\nfor (const b of $('stTabs').querySelectorAll('button')) b.onclick = () => switchCfgTab(b.dataset.tab)\r\n\r\n$('renameBtn').onclick = async () => {\r\n  const name = $('renameInput').value.trim()\r\n  if (name === '' || settingsAgent === null) return\r\n  const r = await fetch('/api/update', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: settingsAgent.id, name }) }).then((x) => x.json())\r\n  if (r.error !== undefined) { alert(String(r.error)); return }\r\n  $('renameInput').value = ''\r\n  await loadAgents()\r\n}\r\n\r\n// ---------- 第一视角时间线 ----------\r\n\r\nfunction renderTimeline(items) {\r\n  timeline.innerHTML = ''\r\n  liveHost = null // 历史整建：live 尾层随 next paint 重建\r\n  for (const it of items) {\r\n    if (it.kind === 'meta') { timeline.appendChild(msgEl('meta', it.icon + '  ' + it.text)); continue }\r\n    if (it.kind === 'tool') { timeline.appendChild(toolLineEl(it.text, it.who, it.toolName)); continue } // 工具结果 = 默认折叠件\r\n    timeline.appendChild(msgEl(it.side, it.text, it.who))\r\n  }\r\n  if (items.length === 0) timeline.appendChild(emptyHint())\r\n  timeline.scrollTop = timeline.scrollHeight\r\n}\r\n\r\n/** 工具结果行折叠件：默认收起一行头 = **工具名**（首行）+ 来源 + 规模；展开看全文。 */\r\nfunction toolLineEl(text, who, toolName) {\r\n  const el = document.createElement('div')\r\n  const tf = toolFold(text)\r\n  el.className = 'toolmsg shut'\r\n  el.title = '点击展开/收起工具输出'\r\n  const head = document.createElement('div')\r\n  head.className = 'thead'\r\n  // 首行格式：`工`（主色图标）+ 工具名（普通色，关联还原；无则回退结果首行）\r\n  // + 末尾字数/行数统计。**不显示调用者**——工具行显然属于当前窗 agent，省略噪音。\r\n  const nameText = toolName ?? (tf === null ? '' : tf.head)\r\n  const meta = tf === null ? '' : tf.meta\r\n  head.innerHTML = `<b class=\"ticon\">${ACT_GLYPH.tool}</b><span class=\"tname\">${esc(nameText)}</span> <span class=\"tcnt\">${esc(meta)}</span>`\r\n  const body = document.createElement('div')\r\n  body.className = 'tbody'\r\n  body.textContent = tf === null ? text : tf.full\r\n  el.appendChild(head)\r\n  el.appendChild(body)\r\n  el.onclick = () => el.classList.toggle('shut')\r\n  return el\r\n}\r\n\r\nfunction emptyHint() {\r\n  const el = document.createElement('div')\r\n  el.id = 'empty'\r\n  if (agentsCache.filter((a) => a.parentId !== null).length === 0) {\r\n    el.innerHTML = '族谱仅根 <b>user#0</b>。<br/>于左下「<b>生</b>」实例化第一位后代，它将成为你的子节点、开启协作。'\r\n  } else {\r\n    el.innerHTML = '从左侧<b>族谱树</b>选择一位后代开始对话。'\r\n  }\r\n  return el\r\n}\r\n\r\nfunction msgEl(cls, text, who) {\r\n  const el = document.createElement('div')\r\n  el.className = 'msg ' + cls\r\n  if (who) el.innerHTML = `<div class=\"who\">${esc(who)}</div>`\r\n  if (cls === 'tool' || cls === 'meta') {\r\n    el.appendChild(document.createTextNode(text)) // 非 markdown 通道保原样\r\n  } else {\r\n    const d = document.createElement('div')\r\n    d.className = 'md'\r\n    d.innerHTML = mdToHtml(text)\r\n    el.appendChild(d)\r\n    const cp = document.createElement('button') // hover 复制原文\r\n    cp.className = 'copyBtn'; cp.textContent = '複'; cp.title = '复制原文'\r\n    cp.onclick = () => { void navigator.clipboard?.writeText(text) }\r\n    el.appendChild(cp)\r\n  }\r\n  return el\r\n}\r\n\r\nasync function loadContext(id) {\r\n  if (id !== currentAgentId) return // 快速连点防御：迟到响应不覆盖新选窗口\r\n  const data = await fetch('/api/agents/' + encodeURIComponent(id) + '/context').then((r) => r.json())\r\n  if (id !== currentAgentId) return\r\n  ctxWindow = Number(data.contextWindow) > 0 ? Number(data.contextWindow) : 1000000\r\n  renderTimeline(routeLetters(data.messages || [], id, ROOT_ID, nameOf))\r\n  ctxRatio = contextRatio(data.messages, ctxWindow)\r\n  paintCtxBar(ctxRatio)\r\n  const st = turnStats(data.messages)\r\n  const ts = $('turnStats')\r\n  ts.hidden = !(st.durationS > 0)\r\n  ts.textContent = st.durationS > 0 ? `最近一轮耗时 ${st.durationS.toFixed(1)}s` : '' // 轮数/token 已在信息条\r\n  schedulePaint()\r\n}\r\n\r\n// ---------- 上下文占用进度条（composer 之下铺底，三色带） ----------\r\n\r\nfunction paintCtxBar(ratio) {\r\n  const fill = $('ctxFill')\r\n  fill.style.width = Math.round(ratio * 100) + '%'\r\n  fill.className = ratioTone(ratio)\r\n  $('ctxBar').title = `上下文占用 ${(ratio * 100).toFixed(1)}% / ${ctxWindow.toLocaleString()} tokens`\r\n}\r\n\r\n// ---------- 流式 live 层渲染（rAF 合帧节流；主列尾与抽屉共用 builder） ----------\r\n\r\nfunction liveDom(bucket, id) {\r\n  const frag = document.createDocumentFragment()\r\n  const running = bucket.text === '' // 正文未起 = 还在想\r\n  const rv = reasoningView(bucket.reasoning, running)\r\n  if (rv !== null) {\r\n    // 自定义折叠件（弃 native details）：**默认展开流全文**、点击任意处收起/\r\n    // 展开、收起态只留头行——两态零重复；shut 态记在 bucket 上跨帧存活。\r\n    const d = document.createElement('div')\r\n    const shut = bucket.rShut === true\r\n    d.className = 'reason' + (shut ? ' shut' : '') + (running ? ' running' : '')\r\n    const head = document.createElement('div')\r\n    head.className = 'rsum'\r\n    head.textContent = rv.summary\r\n    const full = document.createElement('div')\r\n    full.className = 'rfull'\r\n    full.innerHTML = mdToHtml(rv.full)\r\n    d.appendChild(head)\r\n    d.appendChild(full)\r\n    d.onclick = () => {\r\n      bucket.rShut = !(bucket.rShut === true)\r\n      d.classList.toggle('shut')\r\n    }\r\n    frag.appendChild(d)\r\n  }\r\n  for (const t of bucket.tools) {\r\n    const chip = document.createElement('div')\r\n    const dur = t.doneAt > 0 && t.doneAt >= t.at ? ' · ' + ((t.doneAt - t.at) / 1000).toFixed(1) + 's' : ''\r\n    chip.className = 'chip ' + t.phase\r\n    chip.textContent = `${ACT_GLYPH.tool} ${t.name} ${t.phase === 'called' ? '执行' : t.phase === 'success' ? '完成' : '失败'}${dur}`\r\n    frag.appendChild(chip)\r\n  }\r\n  if (bucket.text !== '') {\r\n    const b = document.createElement('div')\r\n    b.className = 'msg agent streaming'\r\n    const who = document.createElement('div'); who.className = 'who'; who.textContent = bucketLabel(id)\r\n    b.appendChild(who)\r\n    const d = document.createElement('div')\r\n    d.className = 'md'\r\n    d.innerHTML = mdToHtml(bucket.text)\r\n    b.appendChild(d)\r\n    frag.appendChild(b)\r\n  }\r\n  return frag\r\n}\r\n\r\nconst bucketLabel = (id) => { const a = agentsCache.find((x) => x.id === id); return a !== undefined && a.name !== undefined ? a.name : id }\r\n\r\nfunction nearBottom() { return timeline.scrollHeight - timeline.scrollTop - timeline.clientHeight < 160 }\r\n\r\nfunction renderLive() {\r\n  updateSendState() // 桶出现/收口即时反映到送钮（busy 灰条 / 空闲恢复）\r\n  const b = currentAgentId !== '' ? liveBuckets[currentAgentId] : undefined\r\n  if (b !== undefined) {\r\n    if (liveHost === null || !liveHost.isConnected) {\r\n      liveHost = document.createElement('div')\r\n      liveHost.id = 'liveHost'\r\n      timeline.appendChild(liveHost)\r\n    }\r\n    const stick = nearBottom()\r\n    liveHost.replaceChildren(liveDom(b, currentAgentId))\r\n    if (stick) timeline.scrollTop = timeline.scrollHeight\r\n  } else if (liveHost !== null) {\r\n    liveHost.remove()\r\n    liveHost = null\r\n  }\r\n  if (watchAgentId !== '') {\r\n    const wb = liveBuckets[watchAgentId]\r\n    if (wb !== undefined) {\r\n      const body = $('drawerBody')\r\n      const stick = body.scrollHeight - body.scrollTop - body.clientHeight < 160\r\n      body.replaceChildren(liveDom(wb, watchAgentId))\r\n      if (stick) body.scrollTop = body.scrollHeight\r\n    }\r\n  }\r\n}\r\n\r\nfunction schedulePaint() {\r\n  if (paintQueued) return\r\n  paintQueued = true\r\n  requestAnimationFrame(() => { paintQueued = false; renderLive() })\r\n}\r\n\r\n// ---------- 监督抽屉 ----------\r\n\r\nfunction openDrawer(id) {\r\n  watchAgentId = id\r\n  $('drawer').hidden = false\r\n  $('drawerTitle').textContent = '督 · ' + bucketLabel(id)\r\n  schedulePaint()\r\n}\r\nfunction closeDrawer() {\r\n  if (watchAgentId !== '') clearBucket(liveBuckets, watchAgentId)\r\n  watchAgentId = ''\r\n  $('drawer').hidden = true\r\n  $('drawerBody').innerHTML = ''\r\n}\r\n$('drawerClose').onclick = closeDrawer\r\n\r\n// ---------- 事件流（delta + tool 相进桶；letter 快照收口；status 清画布） ----------\r\n\r\nfunction openStream() {\r\n  const es = new EventSource('/api/events')\r\n  es.onopen = () => {\r\n    $('conn')?.classList.add('on')\r\n    // 快照追平：事件流无回放（SSE 断线/服务端重启窗口会丢 status/letter）——\r\n    // 凡连接建立/重连成功，live 桶与忙态一律作废、以仓库历史为准重建（delta\r\n    // live-only 纪律的另一半：断帧不补，快照自愈）。\r\n    for (const id of Object.keys(liveBuckets)) clearBucket(liveBuckets, id)\r\n    roundBusy = false\r\n    void loadAgents()\r\n    if (currentAgentId !== '') void loadContext(currentAgentId)\r\n    schedulePaint()\r\n    updateSendState()\r\n  }\r\n  es.onmessage = (e) => handleEvent(JSON.parse(e.data))\r\n  es.onerror = () => { $('conn')?.classList.remove('on'); es.close(); setTimeout(openStream, 2000) }\r\n}\r\n\r\nfunction handleEvent(ev) {\r\n  applyStreamEvent(liveBuckets, ev)\r\n  if (ev.type === 'stream' || ev.type === 'tool') {\r\n    if (ev.agentId === currentAgentId || ev.agentId === watchAgentId) schedulePaint()\r\n    return\r\n  }\r\n  if (ev.type === 'letter') {\r\n    const content = (ev.letters && ev.letters[0] && typeof ev.letters[0].content === 'string') ? ev.letters[0].content : ''\r\n    if (ev.agentId === currentAgentId) {\r\n      // 收信只刷新历史（新 user 行上屏）；桶归轮生命周期管，此处不动。\r\n      void loadContext(currentAgentId).catch((e) => console.error('[ui] loadContext@letter', e))\r\n      void loadAgents()\r\n    }\r\n    return\r\n  }\r\n  if (ev.type === 'status') {\r\n    void loadAgents()\r\n    if (ev.agentId === currentAgentId && ev.to === 'thinking') roundBusy = true\r\n    else if (ev.agentId === currentAgentId && (ev.to === 'holding' || ev.to === 'idle' || ev.to === 'interrupted')) {\r\n      // 轮末收口三步全部**同步**（快照拉取失败也绝不让光标/灰钮滞留）：\r\n      // 忙态解除 + 桶清 + 光标退场，然后才尽力刷新历史。\r\n      roundBusy = false\r\n      clearBucket(liveBuckets, ev.agentId)\r\n      schedulePaint()\r\n      void loadContext(currentAgentId).catch((e) => console.error('[ui] loadContext@holding', e))\r\n    }\r\n    if (ev.to === 'thinking') clearBucket(liveBuckets, ev.agentId) // 新轮开画布\r\n    if (ev.agentId === watchAgentId && (ev.to === 'holding' || ev.to === 'idle')) schedulePaint() // 抽屉定格保留到下轮\r\n    updateSendState()\r\n  }\r\n}\r\n\r\n// ---------- 会话动作 ----------\r\n\r\nlet sendAllowed = false\r\nlet roundBusy = false // thinking→holding 之间 = 回复未完整收口，送钮灰防误触\r\nlet sendInFlight = false\r\n\r\nfunction updateSendState() {\r\n  const busy = sendInFlight || roundBusy || (currentAgentId !== '' && liveBuckets[currentAgentId] !== undefined)\r\n  const canSend = sendAllowed && !busy\r\n  $('sendBtn').disabled = !canSend\r\n  $('input').disabled = !sendAllowed\r\n  const a = currentAgent()\r\n  $('input').placeholder = !sendAllowed ? '选择一位后代开始对话…'\r\n    : busy ? `${String(a?.name ?? a?.id ?? '')} 回复中——本轮收口后可继续（消息会合并投递）`\r\n    : `向 ${a?.name ?? a?.id ?? ''} 发消息（Enter 发送，Shift+Enter 换行）`\r\n}\r\n\r\nfunction applyActions(agent) {\r\n  sendAllowed = agent !== null && agent !== undefined && deriveActions(agent).send !== 'off'\r\n  updateSendState()\r\n}\r\n\r\nasync function selectAgent(id) {\r\n  currentAgentId = id\r\n  roundBusy = false // 换窗不复用旧窗的轮忙态（下个 status 事件自然校正）\r\n  // 即点即清屏：旧窗内容零残留（空态占位），数据两请求**并行**拉取——\r\n  // 历史窗口渲染不依赖 agents 行集，串行 await 会让远程主机延迟翻倍。\r\n  timeline.innerHTML = ''\r\n  timeline.appendChild(emptyHint())\r\n  sendAllowed = false\r\n  updateSendState()\r\n  const agentsP = fetch('/api/agents').then((r) => r.json())\r\n  const ctxP = fetch('/api/agents/' + encodeURIComponent(id) + '/context').then((r) => r.json())\r\n  const pair = await Promise.all([agentsP, ctxP]).catch((e) => {\r\n    console.error('[ui] selectAgent 数据拉取失败', e)\r\n    return null\r\n  })\r\n  if (pair === null) return\r\n  const [agents, ctx] = pair\r\n  if (id !== currentAgentId) return // 等待期已切窗：本轮作废\r\n  agentsCache = agents\r\n  const a = agents.find((x) => x.id === id) ?? null\r\n  applyActions(a)\r\n  renderComposerMeta()\r\n  renderQuickBox()\r\n  const msgs = ctx.messages || []\r\n  renderTimeline(routeLetters(msgs, id, ROOT_ID, nameOf))\r\n  ctxWindow = Number(ctx.contextWindow) > 0 ? Number(ctx.contextWindow) : 1000000\r\n  paintCtxBar(contextRatio(msgs, ctxWindow))\r\n  if (a !== null && a.parentId === null) {\r\n    $('turnStats').hidden = true // 根箱无\"轮\"语义（扮演接口不跑 LLM 轮）\r\n  } else {\r\n    const st = turnStats(msgs)\r\n    const ts = $('turnStats')\r\n    ts.hidden = !(st.durationS > 0)\r\n    ts.textContent = st.durationS > 0 ? `最近一轮耗时 ${st.durationS.toFixed(1)}s` : ''\r\n  }\r\n  schedulePaint()\r\n  void loadAgents(agents) // 树重绘复用同一次拉取（高亮换人）\r\n}\r\n\r\nasync function terminateAgent(agent) {\r\n  const id = agent.id\r\n  if (!confirm(`销毁 ${id}？（级联销毁其子树；消息语料保留于仓库）`)) return\r\n  await fetch('/api/terminate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: id, recursive: true }) })\r\n  if (id === currentAgentId) {\r\n    currentAgentId = ''\r\n    $('turnStats').hidden = true\r\n    applyActions(null)\r\n    timeline.innerHTML = ''; timeline.appendChild(emptyHint())\r\n  }\r\n  if (id === watchAgentId) closeDrawer()\r\n  if (settingsAgent !== null && settingsAgent.id === id) closeSettings()\r\n  await loadAgents()\r\n}\r\n\r\n// ---------- 侧栏收起 / 展开 ----------\r\n$('sideToggle').onclick = () => {\r\n  const mini = document.body.classList.toggle('side-mini')\r\n  $('sideToggle').textContent = mini ? '展' : '隠'\r\n  $('sideToggle').title = mini ? '展开侧栏' : '收起侧栏（简化族谱）'\r\n}\r\n\r\n// ---------- 对话与实例化 ----------\r\n\r\nasync function send() {\r\n  const text = $('input').value.trim()\r\n  if (text === '' || !currentAgentId) return\r\n  $('input').value = ''\r\n  sendInFlight = true\r\n  updateSendState()\r\n  try {\r\n    await fetch('/api/send', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ to: currentAgentId, text }) })\r\n  } finally {\r\n    sendInFlight = false\r\n    updateSendState()\r\n  }\r\n}\r\n\r\nasync function createAgent() {\r\n  const className = $('createClass').value\r\n  const userPrompt = $('createPrompt').value.trim() || '你好，请做一个简短的自我介绍。'\r\n  const body = { className, userPrompt }\r\n  const model = $('createModel').value // 空 = 不显式（落类基因>父继承>家学链）\r\n  if (model) body.model = model\r\n  const name = $('createName').value.trim() // 空 = 派生 类名-N\r\n  if (name !== '') body.name = name\r\n  const r = await fetch('/api/instantiate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })\r\n  const data = await r.json()\r\n  if (data.error !== undefined) { alert(String(data.error)); return }\r\n  if (data.agentId) { $('createPrompt').value = ''; $('createName').value = ''; void selectAgent(data.agentId) }\r\n}\r\n\r\nasync function loadTemplates() {\r\n  const templates = await fetch('/api/templates').then((r) => r.json())\r\n  templatesCache = templates\r\n  const sel = $('createClass')\r\n  sel.innerHTML = ''\r\n  for (const t of templates) {\r\n    if (t.panel) continue // 面板类（user/策略 role）不可实例化对话\r\n    sel.appendChild(new Option(t.name, t.name))\r\n  }\r\n}\r\n\r\n$('sendBtn').onclick = send\r\n$('input').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() } })\r\n$('createBtn').onclick = createAgent\r\n\r\nfunction esc(s) { return String(s).replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c])) }\r\n\r\n// ---------- 启动（空桌引导） ----------\r\n;(async () => {\r\n  await loadModels()\r\n  await loadTemplates()\r\n  await loadAgents()\r\n  renderTimeline([])\r\n  applyActions(null)\r\n  openStream()\r\n})()\r\n",
  "index.html": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>stem · WebUIShell</title>\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n<aside>\n  <h1>STEM <small>· 族谱</small><span class=\"ico\" id=\"settingsBtn\" data-state=\"ready\" title=\"设置面板（实例/类配置）\">設</span><span class=\"ico\" id=\"sideToggle\" data-state=\"ready\" title=\"收起侧栏（再点展开）\">隠</span></h1>\n  <div id=\"tree\"></div>\n  <div id=\"createBox\">\n    <h3>实例化后代（user#0 = 根）</h3>\n    <div class=\"qrow\"><label>类</label><select id=\"createClass\" title=\"出生类（工具/策略基因随类）\"></select></div>\n    <div class=\"qrow\"><label>模型</label><select id=\"createModel\" title=\"出生显式模型（模型三环·环一）；缺省 = 类基因>父继承>家学\"></select></div>\n    <div class=\"qrow\"><label>称呼</label><input id=\"createName\" placeholder=\"缺省派生 类名-N（全局唯一）\" /></div>\n    <div class=\"qrow\"><label>提词</label><input id=\"createPrompt\" placeholder=\"首条 user prompt…\" /></div>\n    <button id=\"createBtn\">生 · 实例化</button>\n  </div>\n  <div id=\"quickBox\" hidden>\n    <h3>快捷设置 · <span id=\"quickName\">—</span></h3>\n    <div class=\"qrow\"><label>模型</label><select id=\"modelSel\" title=\"切换运行时模型（下一轮生效，不级联子女）\"></select><span id=\"modelOrigin\" class=\"origin\"></span></div>\n    <div class=\"qrow\"><label>思考程度</label><select id=\"effortSel\" disabled title=\"模型侧推理预算控制（即将上线）\"><option>即将上线</option></select></div>\n  </div>\n</aside>\n<main>\n  <div id=\"timeline\"></div>\n  <div id=\"turnStats\" hidden></div>\n  <div id=\"cBox\">\n    <textarea id=\"input\" placeholder=\"选择一位后代开始对话…\" disabled></textarea>\n    <div id=\"cBar\">\n      <button id=\"attachBtn\" title=\"附件（即将上线）\" data-state=\"off\">附</button>\n      <div id=\"cMeta\"></div>\n      <span id=\"cRight\"><span id=\"agentSt\"></span><span id=\"conn\" title=\"事件流连接\"></span></span>\n      <button id=\"sendBtn\" disabled>送</button>\n    </div>\n  </div>\n  <div id=\"ctxBar\" title=\"上下文窗口占用\"><div id=\"ctxFill\"></div></div>\n</main>\n<div id=\"hoverCard\" hidden></div>\n<div id=\"popover\" hidden></div>\n<div id=\"settingsMask\" hidden>\n  <div id=\"settingsPanel\">\n    <div id=\"stHead\"><span>设置 · <span id=\"stAgent\">—</span></span><span class=\"sp\"></span><span class=\"ico\" id=\"stClose\" title=\"关闭\">閉</span></div>\n    <div id=\"stTabs\">\n      <button data-tab=\"instance\" class=\"on\">实例配置</button>\n      <button data-tab=\"class\">类配置</button>\n    </div>\n    <div id=\"stInstance\" class=\"stPane\">\n      <div class=\"row\"><label>模型</label><select id=\"stModel\" title=\"运行时换模型（下一轮生效，不级联子女）\"></select><span id=\"stModelOrigin\" class=\"origin\"></span></div>\n      <div class=\"row\"><label>思考程度</label><select disabled title=\"模型侧推理预算控制（即将上线）\"><option>即将上线</option></select></div>\n      <div class=\"row\"><input id=\"renameInput\" placeholder=\"新称呼（全局唯一）\" /><button id=\"renameBtn\">改名</button></div>\n      <div class=\"row\"><button data-state=\"off\" title=\"工具收敛清单编辑（后续强化）\">工 · 工具收敛（待强化）</button></div>\n      <div class=\"hint\">此页签写**实例行**参数（运行期）；出生设置见左栏实例化面板。</div>\n    </div>\n    <div id=\"stClass\" class=\"stPane\" hidden>\n      <div class=\"row\"><label>类</label><select id=\"stClassSel\"></select></div>\n      <div class=\"row\"><input id=\"stClassDesc\" placeholder=\"类描述（description）\" /></div>\n      <textarea id=\"stClassPrompt\" rows=\"8\" placeholder=\"系统提示词（systemPrompt）…\"></textarea>\n      <div class=\"row\"><label>策略</label><select id=\"stClassStrategy\"><option value=\"\">继承</option><option value=\"classic\">classic</option><option value=\"none\">none</option><option value=\"cortex\">cortex</option></select><span id=\"stClassTools\" class=\"hint\"></span></div>\n      <div class=\"row\"><button id=\"classSaveBtn\">存 · 更新类定义</button><span id=\"classHint\" class=\"hint\"></span></div>\n      <div class=\"hint\">类更新走宿主进化面（同名合并落盘 .stem/agent/，**只影响后续实例**）；面板/user 类不可编辑。</div>\n    </div>\n  </div>\n</div>\n<div id=\"drawer\" hidden>\n  <div id=\"drawerHead\"><span id=\"drawerTitle\">督</span><span class=\"sp\"></span><span class=\"ico\" id=\"drawerClose\" title=\"关闭监督抽屉\">閉</span></div>\n  <div id=\"drawerBody\"></div>\n</div>\n<div id=\"permission\">\n  <div class=\"title\">审 · 工具访问确认</div>\n  <div class=\"body\" id=\"permBody\"></div>\n  <div class=\"row\">\n    <button class=\"once\" id=\"permOnce\">单次批准</button>\n    <button class=\"always\" id=\"permAlways\">始终批准</button>\n    <button class=\"reject\" id=\"permReject\">拒绝</button>\n  </div>\n</div>\n<script type=\"module\" src=\"/app.js\"></script>\n</body>\n</html>\n",
  "style.css": "/* ============================================================\r\n * shell/webui/style.css —— WebUIShell 样式（OLED 无边框主题）\r\n *\r\n * 设计语言：纯黑底、双色语义（青绿=运行/品红=介入）、消息无边框文档流\r\n * （opencode 风）、composer 容器化（输入框 + 信息条 + 铺底占用条）、\r\n * 细滚动条全主题化、禁横向溢出（内容自适应换行）。\r\n * ============================================================ */\r\n\r\n:root {\r\n  --bg: #000000;            /* OLED 纯黑 */\r\n  --surface: #060708;       /* 极深面板 */\r\n  --border: #1c2026;        /* 主分层线 */\r\n  --border-strong: #2e3540;\r\n  --text: #eef1f3;\r\n  --muted: #6b7480;\r\n  --accent: #3df5c8;        /* 青绿 = 正常/运行/激活 */\r\n  --accent-dim: rgba(61, 245, 200, .16);\r\n  --alert: #ff2ec8;         /* 品红 = 需介入（interrupted / 危险） */\r\n  --alert-dim: rgba(255, 46, 200, .16);\r\n  --warn: #e8c34a;\r\n  --lane-w: 14px;\r\n}\r\n* { box-sizing: border-box; margin: 0; padding: 0; }\r\nhtml, body { height: 100%; overflow: hidden; }\r\nbody { background: var(--bg); color: var(--text); font: 14px/1.55 system-ui, \"PingFang SC\", \"Microsoft YaHei\", sans-serif; display: flex; }\r\n::selection { background: var(--accent-dim); }\r\n\r\n/* —— 滚动条主题适配（opencode 风：细身透明轨、悬停提亮；WebKit + Firefox 双轨） —— */\r\n::-webkit-scrollbar { width: 10px; height: 10px; }\r\n::-webkit-scrollbar-track { background: transparent; }\r\n::-webkit-scrollbar-thumb { background: #1a1e24; border-radius: 6px; border: 2px solid transparent; background-clip: padding-box; }\r\n::-webkit-scrollbar-thumb:hover { background: #2a323c; background-clip: padding-box; }\r\n* { scrollbar-width: thin; scrollbar-color: #1a1e24 transparent; }\r\n\r\nbutton { background: transparent; color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 4px 12px; cursor: pointer; font-size: 12px; }\r\nbutton:hover { border-color: var(--border-strong); color: var(--accent); }\r\nbutton[data-state=\"off\"] { color: var(--muted); border-color: transparent; cursor: not-allowed; }\r\nbutton[data-state=\"off\"]:hover { color: var(--muted); border-color: transparent; }\r\nselect { background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 4px 6px; font-size: 12px; }\r\nselect:focus { outline: none; border-color: var(--accent); }\r\nselect:disabled { color: var(--muted); }\r\n\r\n/* 三态动作字（R8） */\r\n.ico { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px;\r\n       border: 1px solid var(--border); border-radius: 4px; font-size: 12px; line-height: 1; cursor: pointer; flex: 0 0 auto; }\r\n.ico[data-state=\"off\"] { color: var(--muted); border-color: transparent; cursor: not-allowed;\r\n       background: repeating-linear-gradient(45deg, transparent 0 3px, #0d1013 3px 4px); }\r\n.ico[data-state=\"ready\"] { color: var(--text); border-color: var(--border-strong); }\r\n.ico[data-state=\"ready\"]:hover { color: var(--accent); border-color: var(--accent); }\r\n.ico[data-state=\"active\"] { color: var(--accent); border-color: var(--accent); box-shadow: 0 0 8px var(--accent-dim); }\r\n.ico.danger[data-state=\"ready\"] { color: var(--muted); }\r\n.ico.danger[data-state=\"ready\"]:hover { color: var(--alert); border-color: var(--alert); }\r\n\r\n/* ==================== 左栏：标题+按钮 / 族谱 / 实例化 / 快捷设置 ==================== */\r\naside { width: 320px; min-width: 320px; background: var(--surface); border-right: 1px solid var(--border); display: flex; flex-direction: column; }\r\naside h1 { font-size: 14px; letter-spacing: .06em; padding: 12px 14px; border-bottom: 1px solid var(--border); font-weight: 600; display: flex; align-items: center; gap: 8px; }\r\naside h1 small { color: var(--muted); font-weight: normal; flex: 1; }\r\n\r\n#tree { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 6px 0; }\r\n.tnode { position: relative; display: flex; align-items: center; gap: 6px; padding: 5px 8px 5px 4px; cursor: pointer; border-left: 2px solid transparent; }\r\n.tnode:hover { background: #090b0d; }\r\n.tnode.active { border-left-color: var(--accent); background: #090b0d; }\r\n.tnode .lanes { width: calc(var(--lane-w) * 5); flex: 0 0 auto; height: 24px; }\r\n.tnode .st { font-size: 11px; font-family: ui-monospace, monospace; flex: 0 0 auto; } /* 状态字前置 */\r\n.tnode .st.tone-active { color: var(--accent); }\r\n.tnode .st.tone-alert { color: var(--alert); }\r\n.tnode .st.tone-ready { color: var(--muted); }\r\n.tnode .id { font-family: ui-monospace, monospace; font-size: 12px; font-weight: 600; white-space: nowrap; }\r\n.tnode.active .id { color: var(--accent); }\r\n.tnode.rootnode .id { color: var(--muted); }\r\n.tnode .lp { color: var(--muted); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; min-width: 0; }\r\n.tnode.moren { color: var(--muted); font-size: 11px; font-family: ui-monospace, monospace; padding: 3px 12px 3px 8px; }\r\n.tnode.moren .lanes { height: 18px; }\r\n/* 二级菜单钮：绝对浮动（平时零占位，hover 浮在行上） */\r\n.mbtn { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); opacity: 0; pointer-events: none;\r\n        color: var(--muted); font-size: 11px; background: var(--surface); border: 1px solid var(--border); border-radius: 3px; padding: 0 5px; cursor: pointer; transition: opacity .08s; }\r\n.tnode:hover .mbtn { opacity: 1; pointer-events: auto; }\r\n.mbtn:hover { color: var(--accent); border-color: var(--accent); }\r\n\r\n/* 收起态：只留简化族谱（全名） */\r\nbody.side-mini aside { width: 150px; min-width: 150px; }\r\nbody.side-mini #createBox, body.side-mini #quickBox, body.side-mini .tnode .lanes,\r\nbody.side-mini .tnode .lp, body.side-mini aside h1 small { display: none; }\r\n\r\n#createBox { padding: 10px 12px; border-top: 1px solid var(--border); display: flex; flex-direction: column; gap: 6px; }\r\n#createBox h3, #quickBox h3 { font-size: 11px; color: var(--muted); font-weight: 600; letter-spacing: .08em; }\r\n#createBox .qrow { display: flex; align-items: center; gap: 8px; }\r\n#createBox .qrow label { color: var(--muted); font-size: 11px; flex: 0 0 auto; width: 32px; }\r\n#createBox select, #createBox input { background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 5px 8px; font-size: 12px; flex: 1; min-width: 0; }\r\n#createBox select:focus, #createBox input:focus { outline: none; border-color: var(--accent); }\r\n#createBox button { border-color: var(--accent); color: var(--accent); }\r\n#createBox button:hover { background: var(--accent-dim); }\r\n\r\n#quickBox { border-top: 1px solid var(--border); padding: 10px 12px; display: flex; flex-direction: column; gap: 7px; }\r\n#quickBox[hidden] { display: none; }\r\n#quickBox .qrow { display: flex; align-items: center; gap: 8px; font-size: 12px; }\r\n#quickBox .qrow label { color: var(--muted); flex: 0 0 auto; }\r\n#quickBox select { flex: 1; min-width: 0; color: var(--accent); }\r\n.origin { color: var(--muted); border: 1px solid var(--border); border-radius: 3px; padding: 0 5px; font-size: 11px; flex: 0 0 auto; }\r\n.stPane .row label { color: var(--muted); flex: 0 0 auto; font-size: 12px; }\r\n.stPane .row select { flex: 1; min-width: 0; color: var(--accent); }\r\n.stPane textarea { background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 6px 8px; font-size: 12px; font-family: ui-monospace, monospace; resize: vertical; width: 100%; }\r\n.stPane textarea:focus { outline: none; border-color: var(--accent); }\r\n\r\n/* ==================== 主区：无边框文档流 ==================== */\r\nmain { flex: 1; display: flex; flex-direction: column; min-width: 0; }\r\n#timeline { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 14px 22px 20px; display: flex; flex-direction: column; gap: 10px; }\r\n\r\n/* 消息 = 无边框文档流；me 右对齐；一切内容自适应禁横滚 */\r\n.msg { position: relative; max-width: 86%; min-width: 0; word-break: break-word; overflow-wrap: anywhere; }\r\n.msg.me { align-self: flex-end; }\r\n.msg.agent, .msg.them { align-self: flex-start; }\r\n.msg .who { font-size: 11px; color: var(--muted); margin-bottom: 2px; font-family: ui-monospace, monospace; }\r\n.msg.me .who { color: var(--accent); text-align: right; }\r\n.msg.agent .who, .msg.them .who { color: var(--accent); opacity: .85; } /* 发送者全名标签主题色 */\r\n.msg .md p { margin: 0 0 6px; } .msg .md > :last-child { margin-bottom: 0; }\r\n.msg .md h1, .msg .md h2, .msg .md h3, .msg .md h4, .msg .md h5, .msg .md h6 { margin: 6px 0 4px; font-size: 1.02em; color: var(--accent); }\r\n.msg .md pre { background: #0a0d10; border: 1px solid var(--border); border-radius: 4px; padding: 8px 10px; font-size: 12px; margin: 4px 0; white-space: pre-wrap; word-break: break-word; overflow: hidden; } /* 换行自适应，无横向滚动条 */\r\n.msg .md code { background: #0f1317; border-radius: 3px; padding: 0 4px; font-size: 12px; font-family: ui-monospace, monospace; word-break: break-all; }\r\n.msg .md pre code { background: none; border: none; padding: 0; word-break: break-word; }\r\n.msg .md ul, .msg .md ol { margin: 4px 0 6px 18px; } .msg .md li { margin: 1px 0; }\r\n.msg .md blockquote { border-left: 2px solid var(--muted); color: var(--muted); padding-left: 8px; margin: 4px 0; }\r\n.msg .md table { border-collapse: collapse; margin: 4px 0; font-size: 12px; table-layout: fixed; width: 100%; } /* 固定布局防撑破 */\r\n.msg .md th, .msg .md td { border: 1px solid var(--border); padding: 2px 8px; word-break: break-word; overflow: hidden; } .msg .md th { background: #0a0d10; }\r\n.msg .md a { color: var(--accent); overflow-wrap: anywhere; }\r\n.msg .md hr { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\r\n.toolmsg { align-self: stretch; max-width: 100%; font-family: ui-monospace, monospace; font-size: 11px; color: var(--muted);\r\n            border-left: 2px solid #12151a; padding-left: 8px; cursor: pointer; position: relative; }\r\n.toolmsg:hover { color: var(--text); }\r\n.toolmsg .thead { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-right: 20px; }\r\n.toolmsg .thead::after { content: \"▾\"; position: absolute; right: 4px; color: #3a414b; font-size: 10px; }\r\n.toolmsg.shut .thead::after { content: \"▸\"; }\r\n/* 首行：`工` 图标主色 + 工具名普通色 + 末尾统计；不显调用者 */\r\n.toolmsg .ticon { color: var(--accent); margin-right: 6px; font-weight: 600; }\r\n.toolmsg .tname { color: var(--text); }\r\n.toolmsg .tcnt { color: #3a414b; margin-left: 6px; }\r\n.toolmsg .tbody { display: none; white-space: pre-wrap; word-break: break-word; margin-top: 4px; }\r\n.toolmsg:not(.shut) .tbody { display: block; }\r\n.msg.meta { align-self: stretch; text-align: center; font-size: 11px; color: var(--accent); white-space: pre-wrap; border-top: 1px dashed #12332a; border-bottom: 1px dashed #12332a; padding: 3px; }\r\n.copyBtn { position: absolute; top: 0; right: -26px; width: 22px; height: 18px; padding: 0; font-size: 10px; color: var(--muted); border-color: transparent; }\r\n.msg:hover .copyBtn { border-color: var(--border); }\r\n.copyBtn:hover { color: var(--accent); }\r\n.msg.streaming .md { display: inline; }\r\n.msg.streaming::after { content: \"\"; display: inline-block; width: 7px; height: 1em; margin-left: 1px; vertical-align: -2px;\r\n       border-right: 2px solid var(--accent); animation: blink 1s step-end infinite; }\r\n@keyframes blink { 50% { opacity: 0; } }\r\n\r\n#turnStats { padding: 0 22px 2px; font-size: 11px; color: var(--muted); font-family: ui-monospace, monospace; }\r\n#turnStats[hidden] { display: none; }\r\n\r\n#empty { align-self: center; margin: auto; text-align: center; color: var(--muted); font-size: 13px; max-width: 360px; line-height: 1.8; }\r\n#empty b { color: var(--accent); font-weight: 600; }\r\n\r\n/* —— composer（opencode 风容器：输入框在上、信息条行在下、附件左送右） —— */\r\n#cBox { margin: 0 22px 10px; border: 1px solid var(--border); border-radius: 10px; background: #040506; flex: 0 0 auto; }\r\n#cBox:focus-within { border-color: var(--border-strong); box-shadow: 0 0 0 1px var(--border-strong); }\r\n#input { display: block; width: 100%; resize: none; height: 46px; background: transparent; color: var(--text); border: none; padding: 11px 14px 2px; font-size: 14px; font-family: inherit; }\r\n#input:focus { outline: none; }\r\n#input:disabled { color: var(--muted); cursor: not-allowed; }\r\n#cBar { display: flex; align-items: center; gap: 12px; padding: 4px 10px 7px 12px; min-width: 0; }\r\n#attachBtn { color: var(--muted); border-color: transparent; padding: 2px 8px; font-size: 13px; flex: 0 0 auto; }\r\n#cMeta { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: 14px; font-size: 11px; font-family: ui-monospace, monospace; color: var(--muted); white-space: nowrap; overflow-x: auto; scrollbar-width: none; }\r\n#cMeta::-webkit-scrollbar { display: none; }\r\n#cMeta .item { display: inline-flex; gap: 4px; } #cMeta .k { color: #3a414b; } #cMeta .v { color: var(--text); }\r\n#cMeta .item.head .v { color: var(--accent); font-weight: 600; }\r\n#cRight { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 8px; font-size: 11px; font-family: ui-monospace, monospace; color: var(--muted); }\r\n#cRight.tone-active { color: var(--accent); } #cRight.tone-alert { color: var(--alert); }\r\n#sendBtn { border-color: var(--accent); color: var(--accent); padding: 3px 18px; font-size: 14px; border-radius: 8px; flex: 0 0 auto; }\r\n#sendBtn:hover { background: var(--accent-dim); }\r\n#sendBtn:disabled { border-color: var(--border); color: var(--muted); cursor: not-allowed; background: none; }\r\n\r\n/* —— 上下文占用进度条（最底铺满） —— */\r\n#ctxBar { height: 3px; background: #08090b; flex: 0 0 auto; }\r\n#ctxFill { height: 100%; width: 0; background: var(--accent); transition: width .35s ease; }\r\n#ctxFill.warn { background: var(--warn); } #ctxFill.danger { background: var(--alert); }\r\n\r\n/* ==================== 流式 live 层 ==================== */\r\n#liveHost { display: flex; flex-direction: column; gap: 10px; }\r\n/* 思维链（自定义折叠件）：**默认展开流全文**、点击任意处切换、浅色不斜体无边框，\r\n   与正文以浅色分隔线相隔；收起态只留头行（running=最新行/完成=首行），两态零重复 */\r\n.reason { align-self: flex-start; width: 100%; max-width: 86%; color: var(--muted); font-size: 12px;\r\n          border-bottom: 1px solid var(--border); padding-bottom: 7px; margin-bottom: 9px; cursor: pointer; position: relative; }\r\n.reason::after { content: \"▾\"; position: absolute; right: 2px; top: 0; color: #3a414b; font-size: 10px; }\r\n.reason.shut::after { content: \"▸\"; }\r\n.reason .rsum { display: none; }\r\n.reason.shut .rsum { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\r\n.reason.shut .rfull { display: none; }\r\n.reason.running .rfull::after, .reason.running .rsum::after { content: \" ▍\"; animation: blink 1s step-end infinite; }\r\n.reason .rfull { word-break: break-word; overflow-wrap: anywhere; } /* md 结构渲染，禁 pre-wrap（否则块级换行叠 margin 出双空行） */\r\n.reason .rfull p, .reason .rfull ul, .reason .rfull ol, .reason .rfull li { margin: 0 0 2px; } /* 与浅字正文同距 */\r\n.chip { align-self: flex-start; font-size: 11px; font-family: ui-monospace, monospace; color: var(--muted); border: 1px solid var(--border); border-radius: 10px; padding: 1px 10px; }\r\n.chip.called { color: var(--accent); box-shadow: 0 0 6px var(--accent-dim); }\r\n.chip.success { color: var(--accent); }\r\n.chip.error { color: var(--alert); border-color: var(--alert); }\r\n\r\n/* ==================== 悬浮层：详情卡 / 操作菜单 / 设置面板 / 监督抽屉 / 审 ==================== */\r\n#hoverCard { position: fixed; z-index: 12; width: 260px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 6px; padding: 8px 10px; font-size: 11px; pointer-events: none; box-shadow: 0 4px 18px rgba(0,0,0,.65); }\r\n#hoverCard[hidden] { display: none; }\r\n#hoverCard .t { font-family: ui-monospace, monospace; font-weight: 600; margin-bottom: 4px; }\r\n#hoverCard .r { display: grid; grid-template-columns: auto 1fr; gap: 0 8px; color: var(--muted); }\r\n#hoverCard .r b { color: var(--text); font-weight: normal; text-align: right; font-family: ui-monospace, monospace; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\r\n\r\n#popover { position: fixed; z-index: 13; min-width: 132px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 6px; padding: 4px; display: flex; flex-direction: column; box-shadow: 0 6px 20px rgba(0,0,0,.7); }\r\n#popover[hidden] { display: none; }\r\n#popover button { border: none; text-align: left; padding: 5px 10px; border-radius: 4px; font-size: 12px; }\r\n#popover button:hover { background: #0d1115; }\r\n#popover button.danger:hover { color: var(--alert); background: var(--alert-dim); }\r\n\r\n/* 设置面板（模态：实例配置 / 类配置 双页签——左栏腾出空间后的家） */\r\n#settingsMask { position: fixed; inset: 0; background: rgba(0,0,0,.62); z-index: 20; display: flex; align-items: center; justify-content: center; }\r\n#settingsMask[hidden] { display: none; }\r\n#settingsPanel { width: 520px; max-width: 92vw; max-height: 80vh; overflow-y: auto; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; box-shadow: 0 12px 48px rgba(0,0,0,.8); }\r\n#stHead { display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 600; }\r\n#stHead .sp { flex: 1; }\r\n#stTabs { display: flex; gap: 6px; }\r\n#stTabs button { padding: 2px 12px; font-size: 12px; color: var(--muted); border-color: transparent; }\r\n#stTabs button.on { color: var(--accent); border-color: var(--border); }\r\n.stPane { display: flex; flex-direction: column; gap: 8px; }\r\n.stPane[hidden] { display: none; }\r\n.stPane .row { display: flex; gap: 8px; align-items: center; }\r\n.stPane .row input { flex: 1; min-width: 0; background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 5px 8px; font-size: 12px; }\r\n.stPane .row input:focus { outline: none; border-color: var(--accent); }\r\n#classDef { max-height: 260px; overflow-y: auto; font-size: 12px; font-family: ui-monospace, monospace; color: var(--muted); white-space: pre-wrap; word-break: break-word; background: #040506; border: 1px solid var(--border); border-radius: 4px; padding: 10px; }\r\n.hint { font-size: 11px; color: var(--muted); }\r\n\r\n#drawer { position: fixed; right: 16px; top: 16px; bottom: 16px; width: 380px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 6px; display: flex; flex-direction: column; z-index: 9; padding: 10px 12px; gap: 8px; overflow: hidden; box-shadow: 0 0 24px rgba(0,0,0,.6); }\r\n#drawer[hidden] { display: none; }\r\n#drawerHead { display: flex; align-items: center; gap: 8px; font-size: 12px; font-family: ui-monospace, monospace; color: var(--accent); }\r\n#drawerHead .sp { flex: 1; }\r\n#drawerBody { flex: 1; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; gap: 8px; }\r\n#drawerBody .msg, #drawerBody .reason { max-width: 100%; }\r\n\r\n#permission { position: fixed; left: 50%; transform: translateX(-50%); top: 20px; width: 380px; background: var(--surface); border: 1px solid var(--alert); border-radius: 6px; padding: 14px; display: none; z-index: 24; box-shadow: 0 6px 24px rgba(0,0,0,.7); }\r\n#permission .title { font-weight: 600; margin-bottom: 6px; color: var(--alert); }\r\n#permission .body { color: var(--muted); font-size: 13px; margin-bottom: 12px; }\r\n#permission .row { display: flex; gap: 8px; }\r\n#permission .once { border-color: var(--accent); color: var(--accent); }\r\n#permission .reject { border-color: var(--alert); color: var(--alert); }\r\n\r\n#conn { width: 8px; height: 8px; border-radius: 50%; background: var(--muted); display: inline-block; flex: 0 0 auto; }\r\n#conn.on { background: var(--accent); box-shadow: 0 0 6px var(--accent-dim); }\r\n",
  "view.js": "// ============================================================\r\n// shell/webui/view.js —— WebUI 视图纯函数核心（S6 批 2，R8/R9）\r\n//\r\n// 零 DOM（浏览器经 <script type=\"module\"> import；node:test 直测）。\r\n// 承载八组纯逻辑：\r\n//   1. 汉字字形表（R8：禁 emoji/几何字符，状态/动作全汉字）+ 三态语义；\r\n//   2. 信箱归位 routeLetters（R9 第一视角：根非对话窗口，来信按\r\n//      <sender> 反查归位各 agent 窗）；\r\n//   3. git 风族谱行序 computeTreeRows（DFS + 泳道 + 溢出折叠）；\r\n//   4. 按钮可用性 deriveActions（能力数据驱动，非 agent 特判——\r\n//      根不可销毁等事实全部来自族谱位置，seed #5 就此消除）；\r\n//   5. 流式 live 桶 reducer applyStreamEvent（delta live-only，快照收口）；\r\n//   6. 思维链折叠 reasoningView（running 追最新行 / 结束定格首行）；\r\n//   7. 上下文占用 contextRatio + ratioTone（底部进度条数据层）；\r\n//   8. 零依赖 markdown 子集渲染 mdToHtml（先抽码后转义 = XSS 构造安全）；\r\n//   9. 出生路径 id 自然序 idOrder（族谱显式排序）；\r\n//  10. 二级操作菜单 menuItems / 信息卡 infoRows / 相对时间 relativeTime /\r\n//      对话尾统计 turnStats（批 3：控件收进菜单、hover 详情、统计条——全数据驱动）。\r\n// ============================================================\r\n\r\n/** 本空间根（pilot 扮演身份的约定 id）。 */\r\nexport const ROOT_ID = '0'\r\n\r\n// ---------- 1. 字形表（R8） ----------\r\n\r\n/** 状态字形：静/思/持/断（idle/thinking/holding/interrupted）。 */\r\nexport const STATUS_GLYPH = {\r\n  idle: '静',\r\n  thinking: '思',\r\n  holding: '持',\r\n  interrupted: '断',\r\n}\r\n\r\n/** 动作字形：停/缩/毁/生/送/审/工/摘/我/模。 */\r\nexport const ACT_GLYPH = {\r\n  interrupt: '停',\r\n  compact: '缩',\r\n  terminate: '毁',\r\n  spawn: '生',\r\n  send: '送',\r\n  review: '审',\r\n  tool: '工',\r\n  summary: '摘',\r\n  me: '我',\r\n  model: '模',\r\n}\r\n\r\nexport const statusGlyph = (status) => STATUS_GLYPH[status] ?? '·'\r\n\r\n/** 三态视觉（R8）：off=不可用（遮罩）/ ready=可用（白边框）/ active=激活（荧光）。 */\r\nexport const statusTone = (status) =>\r\n  status === 'thinking' || status === 'holding' ? 'active' : status === 'interrupted' ? 'alert' : 'ready'\r\n\r\n// ---------- 2. 信箱文本（sender 归位原料） ----------\r\n\r\n/** 剥发送者戳：`<sender id=\"name#id\" at=\"yymmdd.hhmm\">…</sender>` → {sender, text}。 */\r\nexport function stripSender(raw) {\r\n  const m = /^<sender id=\"([^\"]+)\"(?: at=\"[^\"]*\")?>([\\s\\S]*?)<\\/sender>$/.exec(String(raw ?? ''))\r\n  if (m) return { sender: m[1] ?? '', text: m[2] ?? '' }\r\n  return { sender: '', text: String(raw ?? '') }\r\n}\r\n\r\n/** 折叠空白并截断（侧栏行摘要用）。 */\r\nexport function truncate(text, max = 30) {\r\n  const flat = String(text ?? '').replace(/\\s+/g, ' ').trim()\r\n  return flat.length > max ? flat.slice(0, max) + '…' : flat\r\n}\r\n\r\n/**\r\n * 信箱消息流 → 时间线渲染描述（R9 第一视角核心，纯函数）。\r\n * item = {kind:'msg'|'tool'|'meta', side:'me'|'agent'|'them', who, text, icon}\r\n * - 常规 agent 窗：user 信按 sender 归位（我=根来信右侧；他 agent 来信左侧）；\r\n * - 根（user#0）窗：反相——assistant = 人类发言（右\"我\"），user = 后代回信（左）；\r\n * - system 不上线；invalid（compact 归档）跳过；tag=summary 出中缝元条。\r\n */\r\nexport function routeLetters(messages, currentId, rootId = ROOT_ID, nameOf) {\r\n  const atRoot = currentId === rootId\r\n  const items = []\r\n  // 预扫：assistant.toolCalls[].id → 工具名（工具结果行据此还原首行工具名）。\r\n  const toolNameById = new Map()\r\n  for (const m of messages ?? []) {\r\n    const tcs = m?.toolCalls ?? []\r\n    for (const tc of tcs) {\r\n      if (tc !== undefined && tc.id !== undefined && tc.name !== undefined) toolNameById.set(String(tc.id), String(tc.name))\r\n    }\r\n  }\r\n  for (const m of messages ?? []) {\r\n    if (!m.valid) continue\r\n    if (m.tag === 'summary') { items.push({ kind: 'meta', icon: ACT_GLYPH.summary, text: '上下文摘要（compact 归档，原文保留可审计）' }); continue }\r\n    const role = m.role\r\n    if (role === 'system') continue\r\n    if (role === 'tool') {\r\n      // 工具结果行：who = 当前 agent 全名（来源）；toolName = 关联的调用名\r\n      //（assistant.toolCalls.id 映射）——首行显工具名，展开看具体内容（用户裁决）。\r\n      const who = nameOf && nameOf(currentId) ? `${String(nameOf(currentId))}#${currentId}` : currentId\r\n      const toolName = toolNameById.get(m?.toolCallId !== undefined ? String(m.toolCallId) : '')\r\n      items.push({ kind: 'tool', icon: ACT_GLYPH.tool, who, toolName, text: String(m.content ?? '') })\r\n      continue\r\n    }\r\n    if (role === 'user') {\r\n      const { sender, text } = stripSender(m.content)\r\n      if (atRoot) {\r\n        // 根窗（呈现面=你）：人类发言（assistant 行）在右；后代回信（user 行）一律在左——标准聊天惯例。\r\n        items.push({ kind: 'msg', side: 'them', who: sender ? `来自 ${sender}` : '来信', text })\r\n      } else {\r\n        // agent 窗（呈现面=该 agent）：**它自己的回复在左，收到的一切消息（根/其它 agent）在右**——\r\n        // 右侧统一对齐（含邮局合并投递的多封），who 仍区分来源（我=根，来自 xxx=它人）。\r\n        const fromRoot = sender === '' || sender === rootId || sender.endsWith('#' + rootId)\r\n        const who = fromRoot ? ACT_GLYPH.me : `来自 ${sender}`\r\n        items.push({ kind: 'msg', side: 'me', who, text })\r\n      }\r\n      continue\r\n    }\r\n    if (role === 'assistant') {\r\n      // 纯 tool-call 轮（正文为空）跳过——无源文本仅漂浮名字误导；工具意图\r\n      // 由紧随的工具结果行承接（who 已标）。有正文的正常渲染全名标签。\r\n      if (String(m.content ?? '').trim() === '') continue\r\n      const who = atRoot ? ACT_GLYPH.me : nameOf && nameOf(currentId) ? `${String(nameOf(currentId))}#${currentId}` : currentId\r\n      items.push({ kind: 'msg', side: atRoot ? 'me' : 'agent', who, text: String(m.content ?? '') })\r\n    }\r\n  }\r\n  return items\r\n}\r\n\r\n// ---------- 3. git 风族谱行序（DFS + 泳道 + 折叠） ----------\r\n\r\n/** 家族分支色板（OLED 低饱和，仅两种主色交替 + 根灰）。 */\r\nexport const FAMILY_PALETTE = ['accent', 'muted', 'alert-soft']\r\n\r\n/**\r\n * 族谱侧栏行序（纯函数，输入 /api/agents 行集）。\r\n * 行 = {type:'node', id, isRoot, depth, lane, parentLane, join（是否画父连线）,\r\n *       passThrough:[穿过本行的祖先泳道], family（家族色 index）, row:{...原 agent 数据}}\r\n *   或 {type:'more', count, kind:'depth'|'siblings', depth, lane}（折叠行「…+n」）。\r\n * 规则（s6-plan §2）：DFS 子序 = 出生序（输入行序）；深 > maxDepth 折叠后代；\r\n * 同父 > maxSiblings 折叠多余；lane 列 = 缩进深度；passThrough 供 SVG 竖线延续。\r\n */\r\nexport function computeTreeRows(agents, opts = {}) {\r\n  const { maxDepth = 4, maxSiblings = 6, rootId = ROOT_ID } = opts\r\n  const list = Array.isArray(agents) ? agents : []\r\n  const byParent = new Map()\r\n  for (const a of list) {\r\n    const key = a.parentId ?? ''\r\n    if (!byParent.has(key)) byParent.set(key, [])\r\n    byParent.get(key).push(a)\r\n  }\r\n  const descendantCount = (id) => {\r\n    let n = 0\r\n    const stack = [id]\r\n    while (stack.length > 0) {\r\n      const cur = stack.pop()\r\n      for (const child of byParent.get(cur) ?? []) { n++; stack.push(child.id) }\r\n    }\r\n    return n\r\n  }\r\n  const roots = list.filter((a) => (a.parentId ?? null) === null)\r\n  // 约定根恒先行（其余无父行为防御性并列根）；同层按出生路径 id 自然序（显式声明，\r\n  // 不依赖输入行序——批 3 项 3）。\r\n  roots.sort((a, b) => (a.id === rootId ? -1 : b.id === rootId ? 1 : idOrder(a.id, b.id)))\r\n  const rows = []\r\n  // 每层记录本层节点的行号，供 passThrough 后处理：有下一兄弟 B 的节点 A，\r\n  // A.lane 竖线在 (rowA, rowB) 开区间各行的背景继续（父泳道贯穿其子树行）。\r\n  const walk = (nodes, depth, parentLane, family) => {\r\n    const lane = depth\r\n    const total = nodes.length\r\n    const visible = total > maxSiblings ? nodes.slice(0, maxSiblings - 1) : nodes\r\n    const levelRowIdx = []\r\n    visible.forEach((node) => {\r\n      levelRowIdx.push(rows.length)\r\n      rows.push({\r\n        type: 'node',\r\n        id: node.id,\r\n        isRoot: (node.parentId ?? null) === null,\r\n        depth: lane,\r\n        lane,\r\n        parentLane,\r\n        join: parentLane !== null,\r\n        passThrough: [],\r\n        family,\r\n        row: node,\r\n      })\r\n      const children = (byParent.get(node.id) ?? []).slice().sort((x, y) => idOrder(x.id, y.id))\r\n      if (children.length > 0) {\r\n        if (depth + 1 > maxDepth) {\r\n          rows.push({ type: 'more', kind: 'depth', count: descendantCount(node.id), depth: lane + 1, lane: lane + 1 })\r\n        } else {\r\n          walk(children, depth + 1, lane, family)\r\n        }\r\n      }\r\n    })\r\n    if (total > visible.length) {\r\n      const hidden = total - visible.length\r\n      let hiddenDescendants = 0\r\n      for (const node of nodes.slice(visible.length)) hiddenDescendants += 1 + descendantCount(node.id)\r\n      rows.push({ type: 'more', kind: 'siblings', count: hidden, descendants: hiddenDescendants, depth: lane, lane })\r\n    }\r\n    // 本层 passThrough 延伸：节点 i 有后继（下一兄弟或折叠 more），lane 背景线贯穿至其后继行前。\r\n    for (let i = 0; i < levelRowIdx.length; i++) {\r\n      const hasSuccessor = i + 1 < visible.length || total > visible.length\r\n      if (!hasSuccessor) continue\r\n      const rowA = levelRowIdx[i]\r\n      const rowB = i + 1 < levelRowIdx.length ? levelRowIdx[i + 1] : rows.length // 折叠 more 收尾：延伸到末尾\r\n      for (let k = rowA + 1; k < rowB; k++) {\r\n        const r = rows[k]\r\n        if (r.passThrough !== undefined && !r.passThrough.includes(lane)) r.passThrough.push(lane)\r\n      }\r\n    }\r\n  }\r\n  walk(roots, 0, null, -1)\r\n  // 家族色：根的每个直接子树一族一色（顶层支系交替，深层沿用）。\r\n  let seq = 0\r\n  for (const r of rows) {\r\n    if (r.type !== 'node') continue\r\n    if (r.parentLane === null) r.family = -1 // 根/并列根 = 灰\r\n    else if (r.depth === 1) r.family = seq++ % 2\r\n  }\r\n  return rows\r\n}\r\n\r\n// ---------- 4. 动作可用性（能力数据驱动，无 agent 特判） ----------\r\n\r\n/**\r\n * 头部动作三态（R8）。事实全部来自族谱位置/面板属性，不认 agent id：\r\n * 根（parentId=null）天然无销毁者 → 毁 off；根面板不跑 LLM/不组装 → 停·缩 off。\r\n * 返回 {send, interrupt, compact, terminate, model}，值 ∈ 'off'|'ready'|'active'。\r\n */\r\nexport function deriveActions(agent) {\r\n  if (agent === null || agent === undefined) {\r\n    return { send: 'off', interrupt: 'off', compact: 'off', terminate: 'off', model: 'off' }\r\n  }\r\n  const isRoot = (agent.parentId ?? null) === null\r\n  return {\r\n    send: isRoot ? 'off' : 'active', // 根非对话窗口（R9）；选中 agent = 对话激活态\r\n    interrupt: isRoot ? 'off' : 'ready',\r\n    compact: isRoot ? 'off' : 'ready',\r\n    terminate: isRoot ? 'off' : 'ready', // 根无祖先 → 销毁权不可达（kernel 同律，UI 只是如实呈现）\r\n    model: 'ready', // 三环自由：任何节点均可设显式层（家学本体仍只经 config 改）\r\n  }\r\n}\r\n\r\n// ---------- 5. 流式 live 层（delta = live-only，快照收口不补间隙——三源共识铁律） ----------\r\n\r\n/** live 桶容器（agentId → {text, reasoning, tools, startedAt, lastAt}）。 */\r\nexport function createLiveBuckets() {\r\n  return Object.create(null)\r\n}\r\n\r\nfunction ensureBucket(buckets, agentId) {\r\n  let b = buckets[agentId]\r\n  if (b === undefined) {\r\n    b = buckets[agentId] = { text: '', reasoning: '', tools: [], startedAt: 0, lastAt: 0 }\r\n  }\r\n  return b\r\n}\r\n\r\n/**\r\n * PilotEvent（SSE JSON 形）→ live 桶就地更新（消费面窄：stream 的 text/reasoning\r\n * delta + tool 相位；其余事件类型恒穿越无副作用）。收口纪律：轮末快照\r\n * （letter → loadContext 重建历史）后由调用方 clearBucket——delta 掉了不补，\r\n * 快照自愈。tool PilotEvent 无 callId → 同名后进先匹配（并行同名=队尾先收口，\r\n * 已知简化；args 刻意不上广播，chip 只显名字/相位/耗时）。\r\n */\r\nexport function applyStreamEvent(buckets, ev) {\r\n  if (ev === null || typeof ev !== 'object') return buckets\r\n  const now = Date.now()\r\n  if (ev.type === 'stream') {\r\n    const e = ev.event ?? {}\r\n    if (e.type === 'text-delta' || e.type === 'reasoning-delta') {\r\n      const b = ensureBucket(buckets, String(ev.agentId))\r\n      if (b.startedAt === 0) b.startedAt = now\r\n      if (e.type === 'text-delta') b.text += String(e.text ?? '')\r\n      else b.reasoning += String(e.text ?? '')\r\n      b.lastAt = now\r\n    }\r\n    return buckets\r\n  }\r\n  if (ev.type === 'tool') {\r\n    const b = ensureBucket(buckets, String(ev.agentId))\r\n    const name = String(ev.tool ?? '?')\r\n    const at = Number(ev.at) > 0 ? Number(ev.at) : now\r\n    if (ev.phase === 'called') {\r\n      b.tools.push({ name, phase: 'called', at, doneAt: 0 })\r\n    } else {\r\n      let matched = false\r\n      for (let i = b.tools.length - 1; i >= 0; i--) {\r\n        const t = b.tools[i]\r\n        if (t.name === name && t.phase === 'called') {\r\n          t.phase = ev.phase === 'error' ? 'error' : 'success'\r\n          t.doneAt = at\r\n          matched = true\r\n          break\r\n        }\r\n      }\r\n      if (!matched) b.tools.push({ name, phase: ev.phase === 'error' ? 'error' : 'success', at, doneAt: at }) // 断线迟到收口：孤儿 success/error 也上账\r\n    }\r\n    b.lastAt = now\r\n    return buckets\r\n  }\r\n  return buckets\r\n}\r\n\r\nexport function clearBucket(buckets, agentId) {\r\n  delete buckets[agentId]\r\n}\r\n\r\n// ---------- 5b. 出生路径 id 自然序与族谱显式排序 ----------\r\n\r\n/** 出生路径 id（`0` / `2` / `1.10`）逐段数值比较（'1.10' > '1.2'，字符串序会错）。 */\r\nexport function idOrder(a, b) {\r\n  const pa = String(a).split('.')\r\n  const pb = String(b).split('.')\r\n  const n = Math.max(pa.length, pb.length)\r\n  for (let i = 0; i < n; i++) {\r\n    const va = i < pa.length ? Number(pa[i]) : -1\r\n    const vb = i < pb.length ? Number(pb[i]) : -1\r\n    if (va !== vb) return va - vb\r\n  }\r\n  return 0\r\n}\r\n\r\n// ---------- 5c. 二级操作菜单 / 信息面板（数据驱动，无 agent 特判） ----------\r\n\r\n/**\r\n * 树行「⋯」菜单项（批 3 项 4：缩/停/毁从 header 收进本菜单）。state 全由\r\n * deriveActions 派生（族谱位置事实），督对根 off（面板不跑轮、无 live 流）。\r\n */\r\nexport function menuItems(agent) {\r\n  if (agent === null || agent === undefined) return []\r\n  const acts = deriveActions(agent)\r\n  const isRoot = (agent.parentId ?? null) === null\r\n  const items = [{ key: 'open', label: '对话', state: isRoot ? 'ready' : 'active' }]\r\n  items.push({ key: 'watch', label: '监督', state: isRoot ? 'off' : 'ready' })\r\n  if (!isRoot) {\r\n    items.push({ key: 'interrupt', label: '中断', state: acts.interrupt })\r\n    items.push({ key: 'compact', label: '压缩', state: acts.compact })\r\n  }\r\n  items.push({ key: 'rename', label: '改名', state: 'ready' })\r\n  items.push({ key: 'instanceCfg', label: '实例配置', state: 'ready' })\r\n  items.push({ key: 'classCfg', label: '类配置', state: 'ready' })\r\n  items.push({ key: 'terminate', label: '销毁', state: acts.terminate, danger: true })\r\n  return items\r\n}\r\n\r\n/** 信息卡/悬浮详情共用的字段行（全名、类、策略、token、最近活跃…）。 */\r\nexport function infoRows(agent, now = Date.now()) {\r\n  if (agent === null || agent === undefined) return []\r\n  const rows = [\r\n    { k: '全名', v: `${agent.name ?? agent.id}#${agent.id}` },\r\n    { k: '类', v: String(agent.classRef ?? '—') },\r\n    { k: '策略', v: String(agent.strategy ?? '—') },\r\n    { k: '状态', v: `${statusGlyph(agent.status)} ${String(agent.status ?? '')}` },\r\n    { k: '轮数', v: String(agent.turnCount ?? 0) },\r\n    { k: '上下文', v: `${Number(agent.ctxTokens ?? 0).toLocaleString()} tokens` },\r\n    { k: '累计', v: `${Number(agent.totalTokens ?? 0).toLocaleString()} tokens` },\r\n    { k: '最近活跃', v: Number(agent.lastActive) > 0 ? relativeTime(Number(agent.lastActive), now) : '—' },\r\n  ]\r\n  if (agent.model) rows.push({ k: '模型', v: `${String(agent.model)}（${ORIGIN_LABELS[agent.modelOrigin] ?? String(agent.modelOrigin ?? '')}）` })\r\n  return rows\r\n}\r\n\r\n/**\r\n * composer 信息条（批 3 布局：header 消失后，当前 agent 关键事实一行横排）。\r\n * 六项：全名 / 模型 / 策略 / 轮次 / 当前上下文 token / 累计 token。\r\n */\r\nexport function composerMeta(agent) {\r\n  if (agent === null || agent === undefined) return []\r\n  return [\r\n    { k: 'agent', v: `${agent.name ?? agent.id}#${agent.id}` },\r\n    { k: '模型', v: String(agent.model ?? '继承链') },\r\n    { k: '策略', v: String(agent.strategy ?? '—') },\r\n    { k: '轮次', v: String(agent.turnCount ?? 0) },\r\n    { k: '上下文', v: `${Number(agent.ctxTokens ?? 0).toLocaleString()}` },\r\n    { k: '累计', v: `${Number(agent.totalTokens ?? 0).toLocaleString()}` },\r\n  ]\r\n}\r\n\r\nconst ORIGIN_LABELS = { explicit: '显式', class: '类基因', inherited: '父继承', home: '家学' }\r\n\r\n/** 相对时刻汉字形（禁 emoji 纪律内：纯文字）。 */\r\nexport function relativeTime(ts, now = Date.now()) {\r\n  const d = Math.max(0, now - Number(ts))\r\n  if (Number(ts) <= 0) return '—'\r\n  if (d < 5000) return '刚刚'\r\n  if (d < 60000) return `${String(Math.floor(d / 1000))} 秒前`\r\n  if (d < 3600000) return `${String(Math.floor(d / 60000))} 分前`\r\n  if (d < 86400000) return `${String(Math.floor(d / 3600000))} 时前`\r\n  return `${String(Math.floor(d / 86400000))} 天前`\r\n}\r\n\r\n/** 对话尾部统计条原料：token 合计 / 轮数 / 最近一轮耗时（末条 user → 末行）。 */\r\nexport function turnStats(messages) {\r\n  const rows = (messages ?? []).filter((m) => m.valid !== false)\r\n  let tokens = 0\r\n  let maxTurn = 0\r\n  let lastUserAt = 0\r\n  let lastAt = 0\r\n  let firstAt = 0\r\n  for (const m of rows) {\r\n    tokens += Number(m.tokens) || 0\r\n    maxTurn = Math.max(maxTurn, Number(m.turn) || 0)\r\n    const at = Number(m.at) || 0\r\n    if (at > 0) {\r\n      if (firstAt === 0) firstAt = at\r\n      lastAt = Math.max(lastAt, at)\r\n      if (m.role === 'user') lastUserAt = Math.max(lastUserAt, at)\r\n    }\r\n  }\r\n  return { tokens, turns: maxTurn, durationS: lastUserAt > 0 && lastAt > lastUserAt ? (lastAt - lastUserAt) / 1000 : 0, firstAt, lastAt }\r\n}\r\n\r\n// ---------- 6. 思维链折叠视图（dsh 式：running 追最新行，结束定格首行） ----------\r\n\r\n/**\r\n * 思维链文本 → 折叠呈现数据。**full = 原文自然序（流式全文）**，展开态只显\r\n * full；summary 仅折叠态头部（running = 最新一行，完成 = 首行）——两态零重复。\r\n * 空 → null 不渲染。\r\n */\r\nexport function reasoningView(text, running) {\r\n  const s = String(text ?? '')\r\n  if (s.trim() === '') return null\r\n  const nonEmpty = s.split('\\n').filter((l) => l.trim() !== '')\r\n  if (nonEmpty.length === 0) return null\r\n  return {\r\n    summary: running ? String(nonEmpty[nonEmpty.length - 1]) : String(nonEmpty[0]),\r\n    full: s,\r\n  }\r\n}\r\n\r\n// ---------- 7. 上下文占用（进度条）与工具行折叠 ----------\r\n\r\n/**\r\n * 工具结果行 → 折叠呈现数据（**默认折叠**，与思维链默认展开相反——用户裁决）：\r\n * head = 首行截断摘要 + 规模提示；expanded 态由渲染层给全文。空 → null。\r\n */\r\nexport function toolFold(text, max = 72) {\r\n  const s = String(text ?? '')\r\n  if (s.trim() === '') return null\r\n  const first = s.split('\\n', 1)[0] ?? ''\r\n  const lines = s.split('\\n').length\r\n  const meta = `${String(s.length).toLocaleString()} 字 · ${String(lines)} 行`\r\n  return { head: truncate(first, max), meta, full: s }\r\n}\r\n\r\n/** 生效行 token 合计 ÷ 模型窗口上限（valid=false 的 compact 归档行不计）。 */\r\nexport function contextRatio(messages, window) {\r\n  const cap = Number(window) > 0 ? Number(window) : 1000000\r\n  let sum = 0\r\n  for (const m of messages ?? []) {\r\n    if (m.valid === false) continue\r\n    sum += Number(m.tokens) || 0\r\n  }\r\n  return Math.min(sum / cap, 1)\r\n}\r\n\r\n/** 三色带：<20% ok（绿）/ 20~40% warn（黄）/ >40% danger（红）。 */\r\nexport function ratioTone(ratio) {\r\n  return ratio < 0.2 ? 'ok' : ratio < 0.4 ? 'warn' : 'danger'\r\n}\r\n\r\n// ---------- 8. 极简 markdown 渲染（零依赖；先抽码后转义再结构 = XSS 构造安全） ----------\r\n\r\nconst escapeHtml = (s) =>\r\n  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;')\r\n\r\n/** 行内强调/链接（输入已 HTML 转义；占位符 \\u0000I<idx>\\u0000 为纯字母数字不受影响）。 */\r\nfunction inlineMd(s) {\r\n  return s\r\n    .replace(/\\*\\*\\*([^*]+)\\*\\*\\*/g, '<b><i>$1</i></b>')\r\n    .replace(/\\*\\*([^*]+)\\*\\*/g, '<b>$1</b>')\r\n    .replace(/(^|[\\s(（])\\*([^*\\n]+)\\*(?=$|[\\s).,!?;:、」』])/, '$1<i>$2</i>') // 单星斜体首处（防乘法噪音，保守只换第一处）\r\n    .replace(/(^|[\\s(（])_([^_\\n]+)_(?=$|[\\s).,!?;:、」』])/g, '$1<i>$2</i>')\r\n    .replace(/\\[([^\\]]+)\\]\\((https?:[^)\\s]+|\\/[^)\\s]*)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>')\r\n}\r\n\r\n/**\r\n * markdown 子集 → HTML（流式容错：未闭合 ``` 视为到文末代码块）。\r\n * 支持：围栏代码块 / 行内码 / 标题 / 引用 / 无序·有序列表 / 表格（含分隔行）/\r\n * hr / 粗斜体 / 链接 / 段落（单换行 <br/>）。\r\n */\r\nexport function mdToHtml(raw) {\r\n  const src = String(raw ?? '')\r\n  if (src.trim() === '') return ''\r\n  // 1) 抽围栏代码块与行内码为占位符（内容不进转义流水线，还原时各自 escape）。\r\n  const fences = []\r\n  const texts = []\r\n  let text = src\r\n    .replace(/```([\\s\\S]*?)(?:```|$)/g, (_m, code) => {\r\n      fences.push(code.replace(/^[^\\n]*\\n/, '').replace(/\\n$/, '')) // 首行语言标忽略\r\n      return `\\u0000B${fences.length - 1}\\u0000`\r\n    })\r\n    .replace(/`([^`\\n]+)`/g, (_m, c) => {\r\n      texts.push(c)\r\n      return `\\u0000I${texts.length - 1}\\u0000`\r\n    })\r\n  const lines = escapeHtml(text).split('\\n')\r\n  const out = []\r\n  let para = []\r\n  let list = null\r\n  const flushPara = () => {\r\n    if (para.length > 0) {\r\n      out.push('<p>' + para.map(inlineMd).join('<br/>') + '</p>')\r\n      para = []\r\n    }\r\n  }\r\n  const flushList = () => {\r\n    if (list !== null) {\r\n      out.push(`</${list}>`)\r\n      list = null\r\n    }\r\n  }\r\n  const fenceOnly = (line) => /^\\u0000B(\\d+)\\u0000$/.exec(line.trim())\r\n  const restoreFence = (m, i) => `<pre><code>${escapeHtml(fences[Number(i)])}</code></pre>`\r\n  for (let li = 0; li < lines.length; li++) {\r\n    const line = lines[li]\r\n    const f = fenceOnly(line)\r\n    if (f !== null) {\r\n      flushPara()\r\n      flushList()\r\n      out.push(restoreFence('', f[1]))\r\n      continue\r\n    }\r\n    const h = /^(#{1,6})\\s+(.*)$/.exec(line)\r\n    if (h !== null) {\r\n      flushPara()\r\n      flushList()\r\n      out.push(`<h${String(h[1].length)}>${inlineMd(h[2])}</h${String(h[1].length)}>`)\r\n      continue\r\n    }\r\n    if (/^(-{3,}|\\*{3,}|_{3,})\\s*$/.test(line.trim())) {\r\n      flushPara()\r\n      flushList()\r\n      out.push('<hr/>')\r\n      continue\r\n    }\r\n    const q = /^&gt;\\s?(.*)$/.exec(line)\r\n    if (q !== null) {\r\n      flushPara()\r\n      flushList()\r\n      out.push(`<blockquote>${inlineMd(q[1])}</blockquote>`)\r\n      continue\r\n    }\r\n    // 表格：| 开头行 + 下一行为分隔行（---|---）触发。\r\n    if (/^\\s*\\|.*\\|\\s*$/.test(line) && /^\\s*\\|[\\s:|-]+\\|\\s*$/.test(lines[li + 1] ?? '')) {\r\n      flushPara()\r\n      flushList()\r\n      const cells = (row) => row.trim().replace(/^\\||\\|$/g, '').split('|').map((c) => inlineMd(c.trim()))\r\n      const rows = [cells(line)]\r\n      li += 1\r\n      while (li + 1 < lines.length && /^\\s*\\|.*\\|\\s*$/.test(lines[li + 1])) rows.push(cells(lines[++li]))\r\n      out.push(\r\n        '<table><thead><tr>' + rows[0].map((c) => `<th>${c}</th>`).join('') + '</tr></thead><tbody>' +\r\n          rows.slice(1).map((r) => '<tr>' + r.map((c) => `<td>${c}</td>`).join('') + '</tr>').join('') +\r\n          '</tbody></table>',\r\n      )\r\n      continue\r\n    }\r\n    const ul = /^\\s*[-*]\\s+(.*)$/.exec(line)\r\n    const ol = /^\\s*\\d+[.)]\\s+(.*)$/.exec(line)\r\n    if (ul !== null || ol !== null) {\r\n      flushPara()\r\n      const want = ul !== null ? 'ul' : 'ol'\r\n      if (list !== want) {\r\n        flushList()\r\n        out.push(`<${want}>`)\r\n        list = want\r\n      }\r\n      out.push(`<li>${inlineMd(ul !== null ? ul[1] : ol[1])}</li>`)\r\n      continue\r\n    }\r\n    if (line.trim() === '') {\r\n      flushPara()\r\n      flushList()\r\n      continue\r\n    }\r\n    para.push(line)\r\n  }\r\n  flushPara()\r\n  flushList()\r\n  let html = out.join('\\n')\r\n  html = html.replace(/\\u0000B(\\d+)\\u0000/g, restoreFence) // 行内漏网的围栏占位（如围栏后同行文字）降级为代码块\r\n  html = html.replace(/\\u0000I(\\d+)\\u0000/g, (_m, i) => `<code>${escapeHtml(texts[Number(i)])}</code>`)\r\n  return html\r\n}\r\n"
}
export const DASH_STATIC: Readonly<Record<string, string>> = {
  "app.js": "// stem dashboard 前端（自包含 ES module；族谱行序/字形复用 view.js 纯函数核心）\nimport { computeTreeRows, statusGlyph, statusTone, truncate } from '/view.js'\n\nconst $ = (sel) => document.querySelector(sel)\nconst esc = (s) => String(s ?? '').replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]))\nconst num = (n) => (n ?? 0).toLocaleString('zh')\nconst fmtAt = (ms) => (ms ? new Date(ms).toLocaleString('zh-CN', { hour12: false }) : '—')\nconst fmtSize = (b) => (b > 1048576 ? (b / 1048576).toFixed(1) + ' MB' : b > 1024 ? (b / 1024).toFixed(0) + ' KB' : b + ' B')\nconst get = async (url) => { const r = await fetch(url); return r.json() }\nconst post = async (url, body) => (await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })).json()\n\nlet agentsCache = []\nlet msgState = { agentId: '', offset: 0, limit: 100, total: 0 }\nlet rawState = { table: 'instances', offset: 0, limit: 50, total: 0 }\nlet selectedAgent = ''\n\n// ---------- tabs ----------\n$('#tabs').addEventListener('click', (e) => {\n  const btn = e.target.closest('button'); if (!btn) return\n  for (const b of document.querySelectorAll('.tabs button')) b.classList.toggle('on', b === btn)\n  for (const p of document.querySelectorAll('.panel')) p.classList.toggle('on', p.id === `panel-${btn.dataset.tab}`)\n  loadTab(btn.dataset.tab)\n})\n\nasync function loadTab(tab) {\n  if (tab === 'tree') await renderTree()\n  if (tab === 'tokens') await renderTokens()\n  if (tab === 'inventory') await renderInventory()\n  if (tab === 'messages') await renderMessages()\n  if (tab === 'raw') await renderRaw()\n  if (tab === 'cleanup') await renderCleanup()\n}\n\n// ---------- 顶卡 ----------\nasync function renderCards() {\n  const [health, stats] = await Promise.all([get('/api/health'), get('/api/stats')])\n  const env = $('#env')\n  env.innerHTML = `${esc(health.project)} · <span class=\"badge ${health.db ? 'live' : 'nowrite'}\">${health.db ? 'DB 就绪' : 'DB 未出生'}</span>` +\n    `<span class=\"badge ${health.allowWrite ? 'write' : 'nowrite'}\">${health.allowWrite ? '⚠ 写姿态' : '只读'}</span>`\n  const cards = $('#cards')\n  if (!stats.db) {\n    cards.innerHTML = `<div class=\"card\"><h3>空间尚无 DB</h3><div class=\"sub\">该空间还没跑过任何 shell（WebUI/CLI 首次启动即诞生）</div></div>`\n    return\n  }\n  const bs = Object.entries(stats.instances.byStatus).map(([k, v]) => `${statusGlyph(k)}${v}`).join(' ')\n  cards.innerHTML = `\n    <div class=\"card\"><h3>语料行</h3><div class=\"num\">${num(stats.messages.valid)}</div><div class=\"sub\">有效 · 归档 ${num(stats.messages.archived)} · 共 ${num(stats.messages.total)}</div></div>\n    <div class=\"card\"><h3>TOKEN（真实计量）</h3><div class=\"num\">${num(stats.tokensValid)}</div><div class=\"sub\">有效口径 · 含归档 ${num(stats.tokensTotal)}</div></div>\n    <div class=\"card\"><h3>实例</h3><div class=\"num\">${num(stats.instances.total)}</div><div class=\"sub\">${bs || '—'} · 空间 ${stats.spaces}</div></div>\n    <div class=\"card\"><h3>DB</h3><div class=\"num\">${fmtSize(stats.dbBytes)}</div><div class=\"sub\">schema v${stats.schemaVersion} · 最近活动 ${fmtAt(stats.lastActivity)}</div></div>`\n}\n\n// ---------- 族谱树 ----------\nasync function renderTree() {\n  agentsCache = await get('/api/agents')\n  const rows = computeTreeRows(agentsCache)\n  const box = $('#tree')\n  if (rows.length === 0) { box.innerHTML = '<div class=\"meta dim\" style=\"padding:10px\">（DB 中尚无实例）</div>'; return }\n  box.innerHTML = rows.map((r) => {\n    if (r.type === 'more') return `<div class=\"trow ghost\"><span class=\"indent\">${'  '.repeat(r.depth)}</span><span class=\"meta\">… +${r.count}${r.kind === 'depth' ? '（折叠后代）' : '（折叠兄弟）'}</span></div>`\n    const a = r.row\n    const tone = statusTone(a.status)\n    const bits = [a.classRef, a.model ?? '', a.msgs + ' 行', num(a.tokens) + ' tk', a.turnCount + ' 轮', a.totalCost > 0 ? 'cost ' + a.totalCost.toFixed(2) : ''].filter(Boolean).join(' · ')\n    return `<div class=\"trow ${selectedAgent === a.id ? 'selected' : ''}\" data-id=\"${esc(a.id)}\">\n      <span class=\"indent\">${'│ '.repeat(r.depth)}${r.join ? '└' : ''}</span>\n      <span class=\"glyph g-${tone}\">${statusGlyph(a.status)}</span>\n      <span class=\"id\">${esc(a.id)}</span>\n      <span class=\"meta\">${esc(bits)}</span>\n      <span class=\"prompt\">${esc(truncate(a.lastPrompt ?? '', 36))}</span>\n    </div>`\n  }).join('')\n  box.querySelectorAll('.trow[data-id]').forEach((el) => el.addEventListener('click', () => {\n    selectedAgent = el.dataset.id\n    renderTree()\n  }))\n}\n\n// ---------- token 账目 ----------\nasync function renderTokens() {\n  const t = await get('/api/tokens')\n  const agentName = new Map(agentsCache.map((a) => [a.id, a.classRef ?? a.id]))\n  const max = Math.max(1, ...t.byAgent.map((x) => x.tokens))\n  const byAgent = t.byAgent.map((x) => {\n    const r = x.byRole ?? {}, w = (v) => Math.max(0, Math.round((v / max) * 240))\n    const stack = `<span class=\"stack\" title=\"user ${num(r.user ?? 0)} / assistant ${num(r.assistant ?? 0)} / tool ${num(r.tool ?? 0)} / system ${num(r.system ?? 0)}\">\n      <i class=\"hbar seg-r\" style=\"width:${w(r.user ?? 0)}px\"></i><i class=\"hbar\" style=\"width:${w(r.assistant ?? 0)}px\"></i>\n      <i class=\"hbar seg-t\" style=\"width:${w(r.tool ?? 0)}px\"></i><i class=\"hbar seg-s\" style=\"width:${w(r.system ?? 0)}px\"></i></span>`\n    const tags = Object.entries(x.byTag ?? {}).map(([k, v]) => `${k} ${num(v)}`).join(' · ')\n    return `<tr><td>${esc(agentName.get(x.agentId) ?? '')} <span class=\"dim\">${esc(x.agentId)}</span></td>\n      <td class=\"num\">${num(x.msgs)}</td><td class=\"num\">${num(x.tokens)}</td><td>${stack}</td><td class=\"dim\">${esc(tags)}</td></tr>`\n  }).join('')\n  const days = t.byDay.map((d) => {\n    const w = Math.max(2, Math.round((d.tokens / Math.max(1, ...t.byDay.map((x) => x.tokens))) * 260))\n    return `<tr><td>${esc(d.day)}</td><td class=\"num\">${num(d.msgs)}</td><td class=\"num\">${num(d.tokens)}</td><td><i class=\"hbar\" style=\"width:${w}px\"></i></td></tr>`\n  }).join('')\n  $('#tokens-body').innerHTML = `\n    <div class=\"hint\">总账：${num(t.total.msgs)} 行 / ${num(t.total.tokens)} tokens（图例：<i class=\"hbar seg-r\"></i> user · <i class=\"hbar\"></i> assistant · <i class=\"hbar seg-t\"></i> tool · <i class=\"hbar seg-s\"></i> system）</div>\n    <table><tr><th>agent</th><th class=\"num\">行</th><th class=\"num\">tokens</th><th>角色堆叠</th><th>tag 分项</th></tr>${byAgent || '<tr><td colspan=5 class=\"dim\">空</td></tr>'}</table>\n    <h4 class=\"dim\" style=\"margin-top:14px\">按日</h4>\n    <table><tr><th>日</th><th class=\"num\">行</th><th class=\"num\">tokens</th><th></th></tr>${days || '<tr><td colspan=4 class=\"dim\">空</td></tr>'}</table>`\n}\n\n// ---------- 资源清单 ----------\nasync function renderInventory() {\n  const inv = await get('/api/inventory')\n  const issues = (inv.initIssues ?? []).length > 0\n    ? `<div class=\"issues\"><b>装载 issue（fail-soft 已跳过，不炸启动）</b>${inv.initIssues.map((i) => `<div>[${esc(i.kind)}] ${esc(i.file)} — ${esc(i.message)}</div>`).join('')}</div>` : ''\n  const toolsByKind = { internal: [], extension: [], custom: [] }\n  for (const t of inv.tools) (toolsByKind[t.kind] ?? toolsByKind.internal).push(t)\n  const toolRow = (t) => `<tr><td class=\"id\">${esc(t.id)}</td><td>${esc(t.accessKey)}</td>\n    <td>${t.visibleToRoot ? '<span class=\"g-accent\">可见</span>' : '<span class=\"dim\">隐藏/deny</span>'}</td><td class=\"dim\">${esc(truncate(t.description, 90))}</td></tr>`\n  const classes = inv.classes.map((c) => `<tr><td><span class=\"badge-l ${c.layer}\">${c.layer}</span>${esc(c.name)}${c.panel ? '<span class=\"tag\">panel</span>' : ''}</td>\n    <td>${c.model ? esc(c.model) : '<span class=\"dim\">继承</span>'}</td><td class=\"num\">${c.toolKeys}</td><td class=\"dim\">${esc(truncate(c.description, 80))}</td></tr>`).join('')\n  const providers = Object.entries(inv.providers ?? {}).map(([name, p]) =>\n    `<tr><td>${esc(name)}</td><td class=\"dim\">${esc(p.baseUrl)}</td><td>${p.keyPresent ? '<span class=\"g-accent\">key ✓</span>' : '<span class=\"g-alert\">key 缺失</span>'}</td><td class=\"dim\">${(p.models ?? []).join(', ') || '全部'}</td></tr>`).join('')\n  $('#inv-body').innerHTML = `${issues}\n    <div class=\"bar\"><span class=\"hint\">家学锚点 <b class=\"g-accent\">${esc(inv.homeModel ?? '—')}</b> · extensions ${esc(JSON.stringify(inv.extensions ?? '默认'))} · 标本装配于 ${fmtAt(inv.assembledAt)}</span></div>\n    <h4><span class=\"badge-l extension\">extension</span>工具（点名启用）</h4>\n    <table><tr><th>id</th><th>访问键</th><th>根可见</th><th>说明</th></tr>${toolsByKind.extension.map(toolRow).join('') || '<tr><td colspan=4 class=\"dim\">无</td></tr>'}</table>\n    <h4><span class=\"badge-l custom\">custom</span>工具（.stem 自动扫描）</h4>\n    <table><tr><th>id</th><th>访问键</th><th>根可见</th><th>说明</th></tr>${toolsByKind.custom.map(toolRow).join('') || '<tr><td colspan=4 class=\"dim\">无</td></tr>'}</table>\n    <h4><span class=\"badge-l internal\">internal</span>系统工具（core 恒在，默认 ignore 隐藏）</h4>\n    <table><tr><th>id</th><th>访问键</th><th>根可见</th><th>说明</th></tr>${toolsByKind.internal.map(toolRow).join('')}</table>\n    <h4>类模板（族谱基因面）</h4>\n    <table><tr><th>类</th><th>基因模型</th><th class=\"num\">tools 键</th><th>说明</th></tr>${classes}</table>\n    <h4>上下文策略（记忆机制清单）</h4>\n    <table><tr><th>策略</th><th>process</th><th>actions</th><th>说明</th></tr>${\n      (inv.strategies ?? []).map((s) => `<tr><td><span class=\"badge-l ${s.layer}\">${s.layer}</span>${esc(s.name)}</td>\n      <td>${s.hasProcess ? '<span class=\"g-accent\">异步许可</span>' : '<span class=\"dim\">纯组装</span>'}</td>\n      <td class=\"dim\">${s.actions.join(', ') || '—'}</td><td class=\"dim\">${esc(truncate(s.note ?? '', 80))}</td></tr>`).join('') || '<tr><td colspan=4 class=\"dim\">无</td></tr>'\n    }</table>\n    <h4>providers（网关注册表）</h4>\n    <table><tr><th>名称</th><th>端点</th><th>密钥</th><th>白名单</th></tr>${providers || '<tr><td colspan=4 class=\"dim\">无</td></tr>'}</table>`\n}\n$('#inv-refresh')?.addEventListener('click', async () => { await get('/api/inventory?refresh=1'); renderInventory() })\n\n// ---------- 语料浏览 ----------\nfunction agentOptions() {\n  const sel = $('#msg-agent')\n  if (sel.options.length <= 1) {\n    for (const a of agentsCache) sel.add(new Option(`${a.id} (${a.classRef})`, a.id))\n    sel.value = msgState.agentId\n  }\n}\nasync function renderMessages() {\n  if (agentsCache.length === 0) agentsCache = await get('/api/agents')\n  agentOptions()\n  const q = new URLSearchParams({ limit: msgState.limit, offset: msgState.offset, ...(msgState.agentId ? { agentId: msgState.agentId } : {}), ...(selectedAgent && !msgState.agentId ? { agentId: selectedAgent } : {}) })\n  if ($('#msg-arch').checked) q.set('archived', '1')\n  const data = await get('/api/messages?' + q)\n  msgState.total = data.total\n  const rows = data.rows.map((m) => `<tr class=\"${!m.valid ? 'dead' : ''}\"><td class=\"dim\">${esc(m.id)}</td>\n    <td><span class=\"role-${esc(m.role)}\">${esc(m.role)}</span>${m.tag ? `<span class=\"tag\">${esc(m.tag)}</span>` : ''}${m.archived ? '<span class=\"tag\">arch</span>' : ''}</td>\n    <td class=\"dim\">${esc(m.agentId)}${m.from ? ` ← ${esc(m.from)}` : ''}</td>\n    <td class=\"num\">${m.turn}.${m.indexInTurn}</td><td class=\"num\">${num(m.tokens)}</td>\n    <td>${esc(m.preview)}</td><td class=\"dim\">${fmtAt(m.at)}</td></tr>`).join('')\n  $('#msg-body').innerHTML = `<table><tr><th>id</th><th>role</th><th>agent</th><th>轮</th><th class=\"num\">tk</th><th>内容预览</th><th>时间</th></tr>${rows || '<tr><td colspan=7 class=\"dim\">空</td></tr>'}</table>`\n  $('#msg-pos').textContent = `${msgState.offset + 1}-${Math.min(msgState.offset + msgState.limit, data.total)} / ${num(data.total)}`\n}\n$('#msg-agent')?.addEventListener('change', (e) => { msgState.agentId = e.target.value; msgState.offset = 0; renderMessages() })\n$('#msg-arch')?.addEventListener('change', renderMessages)\n$('#msg-prev')?.addEventListener('click', () => { msgState.offset = Math.max(0, msgState.offset - msgState.limit); renderMessages() })\n$('#msg-next')?.addEventListener('click', () => { if (msgState.offset + msgState.limit < msgState.total) { msgState.offset += msgState.limit; renderMessages() } })\n\n// ---------- 原表 ----------\nasync function renderRaw() {\n  rawState.table = $('#raw-table').value\n  const data = await get(`/api/raw?table=${rawState.table}&limit=${rawState.limit}&offset=${rawState.offset}`)\n  rawState.total = data.total\n  const head = data.columns.map((c) => `<th>${esc(c)}</th>`).join('')\n  const rows = data.rows.map((r) => `<tr>${data.columns.map((c) => `<td><pre class=\"json\" style=\"max-height:120px;margin:0\">${esc(String(r[c] ?? ''))}</pre></td>`).join('')}</tr>`).join('')\n  $('#raw-body').innerHTML = `<table>${head ? `<tr>${head}</tr>` : ''}${rows || '<tr><td class=\"dim\">空</td></tr>'}</table>`\n  $('#raw-pos').textContent = `${rawState.offset + 1}-${Math.min(rawState.offset + rawState.limit, data.total)} / ${num(data.total)}`\n}\n$('#raw-table')?.addEventListener('change', () => { rawState.offset = 0; renderRaw() })\n$('#raw-prev')?.addEventListener('click', () => { rawState.offset = Math.max(0, rawState.offset - rawState.limit); renderRaw() })\n$('#raw-next')?.addEventListener('click', () => { if (rawState.offset + rawState.limit < rawState.total) { rawState.offset += rawState.limit; renderRaw() } })\n\n// ---------- 清理 ----------\nlet armed = null // 双确认状态机：首次点击装载，二次点击执行\nasync function renderCleanup() {\n  const { preview, allowWrite } = await get('/api/cleanup/preview')\n  $('#cl-mode').innerHTML = allowWrite ? '<span class=\"g-alert\">⚠ 写姿态开启（--allow-write）</span>' : '<span class=\"dim\">只读姿态：动作按钮将拒绝执行（重启加 --allow-write 解锁）</span>'\n  $('#cl-preview').innerHTML = `\n    <table>\n      <tr><th>孤儿消息箱（无实例行）</th><td class=\"num\">${preview.orphanAgents.length} 箱 / ${num(preview.orphanRows)} 行</td><td class=\"dim\">${esc(preview.orphanAgents.slice(0, 8).join(', '))}${preview.orphanAgents.length > 8 ? '…' : ''}</td></tr>\n      <tr><th>terminated 实例（语料 GC 候选）</th><td class=\"num\">${preview.terminatedAgents.length} 个 / ${num(preview.terminatedRows)} 行</td><td class=\"dim\">${esc(preview.terminatedAgents.join(', '))}</td></tr>\n      <tr><th>归档行（archived=1，恢复不加载）</th><td class=\"num\">${num(preview.archivedRows)} 行</td><td class=\"dim\">「销毁保语料」设计留档</td></tr>\n      <tr><th>VACUUM 可回收</th><td class=\"num\">${fmtSize(preview.reclaimableBytes)}</td><td class=\"dim\">freelist × page_size</td></tr>\n    </table>`\n  const dead = agentsCache.filter((a) => a.status === 'terminated')\n  const actions = [\n    { id: 'gc-orphans', title: 'GC 孤儿箱', desc: '删除 instances 表已无对应行的消息箱（历史残留语料）', rows: `${num(preview.orphanRows)} 行` },\n    { id: 'gc-terminated', title: 'GC terminated 语料', desc: '删除 terminated 实例的全部消息行；实例墓碑保留（族谱可考）', rows: `${num(preview.terminatedRows)} 行` },\n    { id: 'purge-agent', title: '定点销毁', desc: '删除指定实例行 + 其全部语料（非 terminated 需勾选风险）', rows: dead.length ? `${dead.length} 个已终止可选` : '' },\n    { id: 'vacuum', title: 'VACUUM 压缩', desc: '回收 freelist 页面，DB 物理缩容', rows: fmtSize(preview.reclaimableBytes) },\n  ]\n  $('#cl-actions').innerHTML = `<div class=\"cl-group\">` + actions.map((a) => `\n    <div class=\"cl-card\"><h4>${a.title}</h4><p>${a.desc}</p>\n      ${a.id === 'purge-agent' ? `<select class=\"picker\" id=\"cl-agent\">${dead.map((d) => `<option value=\"${esc(d.id)}\">${esc(d.id)} (${esc(d.classRef)})</option>`).join('')}</select>` : ''}\n      <div>${a.rows ? `<span class=\"dim\">${a.rows} · </span>` : ''}<button data-act=\"${a.id}\">执行</button></div>\n    </div>`).join('') + `</div>`\n  for (const btn of document.querySelectorAll('#cl-actions button[data-act]')) {\n    btn.addEventListener('click', async () => {\n      const act = btn.dataset.act\n      if (armed !== act) {\n        armed = act\n        for (const b of document.querySelectorAll('#cl-actions button')) { b.classList.remove('confirm'); b.textContent = '执行' }\n        btn.classList.add('confirm'); btn.textContent = '⚠ 再点确认'\n        setTimeout(() => { if (armed === act) { armed = null; btn.classList.remove('confirm'); btn.textContent = '执行' } }, 4000)\n        return\n      }\n      armed = null\n      const body = { action: act, confirm: 'yes' }\n      if (act === 'purge-agent') {\n        const sel = $('#cl-agent')\n        if (!sel?.value) { showResult({ ok: false, note: '下拉无 terminated 实例可定点（先回族谱页刷新）' }); return }\n        body.agentId = sel.value\n      }\n      showResult(await post('/api/cleanup', body))\n      btn.textContent = '执行'\n      await renderCards(); await renderCleanup()\n    })\n  }\n}\nfunction showResult(r) {\n  const el = $('#cl-result')\n  el.classList.remove('hidden')\n  el.innerHTML = `<span class=\"${r.ok ? 'g-accent' : 'g-alert'}\">${r.ok ? '✔' : '✗'} ${esc(r.action)}</span> ${r.deletedRows ? `删除 ${num(r.deletedRows)} 行 · ` : ''}${esc(r.note ?? '')}`\n}\n\n$('#tree-refresh')?.addEventListener('click', renderTree)\n$('#tokens-refresh')?.addEventListener('click', renderTokens)\n$('#cl-refresh')?.addEventListener('click', renderCleanup)\n\n// 启动\nrenderCards().then(renderTree)\n",
  "index.html": "<!doctype html>\n<html lang=\"zh\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>stem · 空间仪表盘</title>\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n<header>\n  <div class=\"brand\">stem<span class=\"dim\">/dashboard</span></div>\n  <div id=\"env\" class=\"env\">…</div>\n</header>\n\n<section id=\"cards\" class=\"cards\"></section>\n\n<nav class=\"tabs\" id=\"tabs\">\n  <button data-tab=\"tree\" class=\"on\">族谱树</button>\n  <button data-tab=\"tokens\">Token 账目</button>\n  <button data-tab=\"inventory\">资源清单</button>\n  <button data-tab=\"messages\">语料浏览</button>\n  <button data-tab=\"raw\">原表</button>\n  <button data-tab=\"cleanup\">清理</button>\n</nav>\n\n<main>\n  <section id=\"panel-tree\" class=\"panel on\">\n    <div class=\"bar\"><button id=\"tree-refresh\">刷新</button><span class=\"hint\">数据源 = DB write-through 实时镜像（含 terminated 墓碑）；缩进即深度，状态字形同 WebUI</span></div>\n    <div id=\"tree\" class=\"tree\"></div>\n  </section>\n\n  <section id=\"panel-tokens\" class=\"panel\">\n    <div class=\"bar\"><button id=\"tokens-refresh\">刷新</button><span class=\"hint\">行级 tokens = 网关真实计量（usage 直记 + 累积差分），估算仅兜底未进网关的行</span></div>\n    <div id=\"tokens-body\"></div>\n  </section>\n\n  <section id=\"panel-inventory\" class=\"panel\">\n    <div class=\"bar\"><button id=\"inv-refresh\">重建标本</button><span class=\"hint\">清单 = bootStem 纯内存标本的装配真实结果（矩阵三态 + 根生效可见集），所见即所跑</span></div>\n    <div id=\"inv-body\"></div>\n  </section>\n\n  <section id=\"panel-messages\" class=\"panel\">\n    <div class=\"bar\">\n      <select id=\"msg-agent\"><option value=\"\">全部 agent</option></select>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"msg-arch\" /> 含归档</label>\n      <button id=\"msg-prev\">← 前页</button><span id=\"msg-pos\"></span><button id=\"msg-next\">后页 →</button>\n    </div>\n    <div id=\"msg-body\"></div>\n  </section>\n\n  <section id=\"panel-raw\" class=\"panel\">\n    <div class=\"bar\">\n      <select id=\"raw-table\"><option>instances</option><option>messages</option><option>spaces</option></select>\n      <button id=\"raw-prev\">←</button><span id=\"raw-pos\"></span><button id=\"raw-next\">→</button>\n    </div>\n    <div id=\"raw-body\"></div>\n  </section>\n\n  <section id=\"panel-cleanup\" class=\"panel\">\n    <div class=\"bar\"><button id=\"cl-refresh\">刷新预览</button><span id=\"cl-mode\"></span></div>\n    <div id=\"cl-preview\"></div>\n    <div id=\"cl-actions\"></div>\n    <div id=\"cl-result\" class=\"result hidden\"></div>\n    <p class=\"warn\">门禁：本仪表盘默认只读；清理需以 <code>--allow-write</code> 重启并逐项 confirm。若同空间 shell（webui/cli）仍在运行，其内存态会写穿覆盖你的删除——先停实例再动手（一进程=一空间是约定，工具不代做检测）。</p>\n  </section>\n</main>\n\n<script type=\"module\" src=\"/app.js\"></script>\n</body>\n</html>\n",
  "style.css": "/* stem dashboard —— OLED 设计语言同 WebUI（纯黑底、边框分层、青绿/品红双色语义） */\n:root {\n  --bg: #000000;\n  --surface: #060708;\n  --border: #1c2026;\n  --border-strong: #2e3540;\n  --text: #eef1f3;\n  --muted: #6b7480;\n  --accent: #3df5c8;\n  --alert: #ff2ec8;\n  --font: \"Cascadia Code\", \"Sarasa Mono SC\", ui-monospace, monospace;\n}\n* { box-sizing: border-box; margin: 0; padding: 0; }\nhtml, body { background: var(--bg); color: var(--text); font: 13px/1.55 var(--font); }\nbutton, select, input { font: inherit; background: var(--surface); color: var(--text); border: 1px solid var(--border-strong); padding: 3px 10px; cursor: pointer; }\nbutton:hover { border-color: var(--accent); color: var(--accent); }\nbutton.confirm { border-color: var(--alert); color: var(--alert); animation: blink 1s infinite; }\n@keyframes blink { 50% { background: #2a0020; } }\na { color: var(--accent); }\n.dim { color: var(--muted); }\n.hidden { display: none !important; }\n\nheader { display: flex; justify-content: space-between; align-items: baseline; padding: 10px 16px; border-bottom: 1px solid var(--border); }\n.brand { color: var(--accent); font-weight: 700; letter-spacing: 1px; }\n.env { color: var(--muted); font-size: 12px; }\n.env .badge { border: 1px solid var(--border-strong); padding: 0 6px; margin-left: 8px; }\n.env .badge.live { color: var(--accent); border-color: var(--accent); }\n.env .badge.nowrite { color: var(--muted); }\n.env .badge.write { color: var(--alert); border-color: var(--alert); }\n\n.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 8px; padding: 12px 16px; }\n.card { border: 1px solid var(--border); background: var(--surface); padding: 10px 12px; }\n.card h3 { font-size: 11px; color: var(--muted); font-weight: 400; letter-spacing: 2px; margin-bottom: 4px; }\n.card .num { font-size: 22px; color: var(--accent); }\n.card .sub { font-size: 11px; color: var(--muted); }\n\n.tabs { display: flex; gap: 4px; padding: 0 16px; border-bottom: 1px solid var(--border); }\n.tabs button { border: 1px solid transparent; border-bottom: none; background: transparent; color: var(--muted); padding: 6px 14px; }\n.tabs button.on { color: var(--accent); border-color: var(--border); border-bottom: 2px solid var(--accent); }\n\nmain { padding: 12px 16px 40px; }\n.panel { display: none; }\n.panel.on { display: block; }\n.bar { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; flex-wrap: wrap; }\n.hint { color: var(--muted); font-size: 11px; }\n.chk { color: var(--muted); font-size: 12px; display: inline-flex; gap: 4px; align-items: center; }\n.chk input { cursor: pointer; }\n\n/* 族谱缩进树 */\n.tree { border: 1px solid var(--border); background: var(--surface); padding: 8px 0; overflow-x: auto; }\n.trow { display: flex; gap: 8px; padding: 2px 12px; white-space: pre; align-items: baseline; cursor: pointer; }\n.trow:hover { background: #0b0f12; }\n.trow.selected { background: #10171a; border-left: 2px solid var(--accent); }\n.trow .indent { color: #232a31; }\n.trow .glyph { font-weight: 700; width: 1.4em; display: inline-block; }\n.g-accent { color: var(--accent); } .g-alert { color: var(--alert); } .g-muted { color: var(--muted); }\n.trow .id { color: var(--accent); }\n.trow .meta { color: var(--muted); font-size: 12px; }\n.trow .prompt { color: var(--text); opacity: .75; font-size: 12px; overflow: hidden; text-overflow: ellipsis; max-width: 40ch; white-space: nowrap; }\n\ntable { border-collapse: collapse; width: 100%; margin: 6px 0 14px; }\nth, td { border: 1px solid var(--border); padding: 3px 8px; text-align: left; font-size: 12px; vertical-align: top; }\nth { color: var(--muted); font-weight: 400; letter-spacing: 1px; background: var(--surface); }\ntd.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }\ntr.dead td { color: var(--muted); text-decoration: line-through; }\ntr.ghost td { color: #3a424b; }\n.role-user { color: var(--alert); } .role-assistant { color: var(--accent); }\n.role-tool { color: #8fa3ff; } .role-system { color: var(--muted); }\n.tag { border: 1px solid var(--border-strong); color: #c8a34d; padding: 0 5px; font-size: 11px; margin-left: 6px; }\n\n.hbar { display: inline-block; height: 9px; background: var(--accent); opacity: .85; vertical-align: middle; }\n.hbar.seg-r { background: var(--alert); } .hbar.seg-t { background: #8fa3ff; } .hbar.seg-s { background: #556; }\n.stack { display: flex; height: 9px; min-width: 2px; }\nsvg.chart { border: 1px solid var(--border); background: var(--surface); margin: 4px 0 14px; }\n\npre.json { border: 1px solid var(--border); background: var(--surface); padding: 8px; font-size: 11px; overflow: auto; max-height: 46vh; }\n\n.badge-l { font-size: 11px; border: 1px solid var(--border-strong); padding: 0 5px; margin-right: 6px; }\n.badge-l.internal { color: var(--muted); } .badge-l.extension { color: var(--accent); border-color: var(--accent); }\n.badge-l.custom { color: #c8a34d; border-color: #6b5a22; } .badge-l.runtime { color: var(--alert); }\n.issues { border: 1px solid #6b5a22; background: #16110a; padding: 8px 12px; margin-bottom: 10px; font-size: 12px; }\n.issues div { color: #d8c07a; }\n\n.result { border: 1px solid var(--border-strong); padding: 8px 12px; margin-top: 10px; white-space: pre-wrap; }\n.warn { color: #a3864f; font-size: 12px; border: 1px dashed var(--border-strong); padding: 8px 12px; margin-top: 14px; }\n.warn code { color: var(--accent); }\n.cl-group { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 8px; margin-bottom: 10px; }\n.cl-card { border: 1px solid var(--border); background: var(--surface); padding: 10px 12px; }\n.cl-card h4 { color: var(--text); font-weight: 400; margin-bottom: 4px; }\n.cl-card p { color: var(--muted); font-size: 11px; min-height: 3em; }\nselect.picker { margin-top: 6px; width: 100%; }\n"
}
